INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べることと飲むこと。", "primary_collocate": null, "pronunciation": "いんしょく", "ipa": "iɴɕokɯ", "syllable_count": 4, "sentences": [{"text": "館内での飲食は禁止です。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "ここで飲食してもいいですか。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "電車の中の飲食は控えてください。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "図書館では飲食ができません。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "祭りで飲食を楽しんだ。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "飲食のマナーを守ろう。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "旅行の飲食にお金を使った。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "教室で飲食しないでください。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "公園では飲食が許されている。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "会の飲食は全部無料だった。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食する", "label": "派生"}, {"form": "飲食物", "label": "派生"}, {"form": "飲食代", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 食べることと飲むこと全般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-41