INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38939, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "飲み物や食べ物を口から体に入れること。", "primary_collocate": null, "pronunciation": "いんしょく", "ipa": "iɴɕokɯ", "syllable_count": 4, "sentences": [{"text": "検査の前は飲食をしないでください。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "手術の後、飲食が許された。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "祖父は自分で飲食できない。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "病気で飲食がつらくなった。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "飲食の量を毎日記録している。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "朝から何も飲食していない。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "医者に飲食を止められている。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "夜遅くの飲食は体に悪い。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "飲食のあとは歯を磨こう。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}, {"text": "熱があっても飲食は大切だ。", "target_word": "飲食", "complexity_tier": "T3", "furigana": "いんしょく", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食する", "label": "派生"}, {"form": "飲食物", "label": "派生"}, {"form": "飲食代", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 飲み物や食べ物を体に入れる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-416b-9300-00acc2ac5b58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38952, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じような種類のもの。似ているもの。", "primary_collocate": null, "pronunciation": "るいじ", "ipa": "ɾɯiʑi", "syllable_count": 3, "sentences": [{"text": "この商品には類似のものが多い。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似の事件が前にもあった。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似の問題を三つ解いた。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "ほかにも類似のアプリがある。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似の例を探してみよう。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "店で類似の服を見つけた。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似のゲームはたくさんある。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "この本と類似の話を読んだ。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似の意見が多く出た。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似のものに注意してください。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "類似する", "label": "派生"}, {"form": "類似品", "label": "派生"}, {"form": "類似点", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 同じような種類の似たもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-416b-9300-00acc2a