INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38953, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほかのものと比べて、形や性質がよく似ていること。", "primary_collocate": null, "pronunciation": "るいじ", "ipa": "ɾɯiʑi", "syllable_count": 3, "sentences": [{"text": "二つの絵はよく類似している。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "兄弟の声は類似している。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "その形は星に類似している。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "二つの言葉の類似に気づいた。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似した色の服を着ている。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "名前が類似していて困る。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "二つの国の文化には類似が見られる。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "顔の類似にみんな驚いた。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "この犬は狼に類似している。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}, {"text": "類似した事故がまた起きた。", "target_word": "類似", "complexity_tier": "T3", "furigana": "るいじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "類似する", "label": "派生"}, {"form": "類似した", "label": "活用"}, {"form": "類似点", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 形や性質がよく似ていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-416b-93