INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38972, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "決まりを実際に使い始めること。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "新しい規則の施行は来月だ。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "その法律は四月に施行された。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "ルールの施行で町が変わった。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "学校が新しい校則を施行した。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "施行の日が近づいている。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "条例の施行に反対の声もある。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "市は新しい決まりを施行する。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "施行の前に説明会を開いた。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "規則は先週から施行されている。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "法の施行が一年遅れた。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "施行する", "label": "派生"}, {"form": "施行される", "label": "活用"}, {"form": "施行日", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 決まりを実際に使い始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-416b-9300-00acc