INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38973, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律や規則を実際に適用し、効力を持たせること。", "primary_collocate": null, "pronunciation": "しこう", "ipa": "ɕikoː", "syllable_count": 3, "sentences": [{"text": "法律の施行で罰金が上がった。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "国が新しい法律を施行した。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "改正法は来年施行される。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "施行の後、事故が減った。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "この法律は施行されている。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "新法の施行に注目が集まる。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "政府は規則を早く施行したい。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "施行の時期はまだ決まらない。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "法の施行には準備がいる。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}, {"text": "税の新制度が施行された。", "target_word": "施行", "complexity_tier": "T3", "furigana": "しこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "施行する", "label": "派生"}, {"form": "施行される", "label": "活用"}, {"form": "施行令", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 法律や規則に効力を持たせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '150ac274-d46f-416b-9300-0