INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39042, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほかの国よりも、ずっと進んでいること。", "primary_collocate": null, "pronunciation": "せんしん", "ipa": "seɰ̃ɕiɴ", "syllable_count": 4, "sentences": [{"text": "この国は医療の面で先進の地位にある。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国々が会議を開いた。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "日本は技術で先進の立場にある。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国から学ぶことは多い。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "その国は環境対策で先進の立場にある。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国と協力して研究する。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国の例を調べてみた。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国でも課題はある。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "この国は福祉で先進の例として有名だ。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}, {"text": "先進の国ほど人口が減っている。", "target_word": "先進", "complexity_tier": "T3", "furigana": "せんしん", "sentence_source": "generated"}], "morphological_forms": [{"form": "先進的", "label": "派生"}, {"form": "先進国", "label": "派生"}, {"form": "先進性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他国よりずっと進んでいること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL