INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39079, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "壊す", "is_correct": true, "explanation": "正しい音「こわす」。"}, {"text": "交わす", "is_correct": false, "explanation": "かわす：一拍目が違う。"}, {"text": "怖い", "is_correct": false, "explanation": "こわい：三拍目が違う。"}, {"text": "くわす", "is_correct": false, "explanation": "くわす（食わす）：一拍目が違う。"}, {"text": "こなす", "is_correct": false, "explanation": "こなす：二拍目が違う。"}, {"text": "越す", "is_correct": false, "explanation": "こす：二拍目「わ」がない。"}], "explanations": {"壊す": "正しい音「こわす」。", "交わす": "かわす：一拍目が違う。", "怖い": "こわい：三拍目が違う。", "くわす": "くわす（食わす）：一拍目が違う。", "こなす": "こなす：二拍目が違う。", "越す": "こす：二拍目「わ」がない。"}, "sentence_index": null, "correct_answer": "壊す"}, "level_3": {"options": [{"text": "壊し", "is_correct": true, "explanation": "落として皿を割ったという意味で合う。"}, {"text": "洗っ", "is_correct": false, "explanation": "落として洗ってしまった、はつながらない。"}, {"text": "作っ", "is_correct": false, "explanation": "落として作る、は意味が通らない。"}, {"text": "買っ", "is_correct": false, "explanation": "落として買う、は意味が通らない。"}], "explanations": {"壊し": "落として皿を割ったという意味で合う。", "洗っ": "落として洗ってしまった、はつながらない。", "作っ": "落として作る、は意味が通らない。", "買っ": "落として買う、は意味が通らない。"}, "sentence_index": 0, "correct_answer": "壊し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晴れた日に音楽を壊して聞いた。", "explanation": "音楽は聞くもの。形のある物ではなく壊せない。"}, {"text": "母は毎朝おいしいご飯を壊している。", "explanation": "ご飯は作るもの。ここで「壊す」は使えない。"}, {"text": "本を静かに壊して勉強した。", "explanation": "本を読む意味で「壊す」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8d27b0-1504-4231-aff3-1c64a5381f44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_ba