INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39079, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「靴」は壊された物なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "「靴が壊した」とは言えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は道具や場所。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所。"}], "correct_answer": "を", "explanations": {"を": "「靴」は壊された物なので「を」。", "が": "「靴が壊した」とは言えない。", "で": "「で」は道具や場所。", "に": "「に」は相手や場所。"}, "error_tags": {"が": "subject_marker", "で": "instrument", "に": "target_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直す", "is_correct": true, "explanation": "壊れた物を使えるようにするので反対。"}, {"text": "割る", "is_correct": false, "explanation": "割るは壊すと近い意味。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは反対ではない。"}, {"text": "借りる", "is_correct": false, "explanation": "借りるは反対ではない。"}], "correct_answer": "直す", "explanations": {"直す": "壊れた物を使えるようにするので反対。", "割る": "割るは壊すと近い意味。", "磨く": "磨くは反対ではない。", "借りる": "借りるは反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8d27b0-1504-4231-aff3-1c64a5381f44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
