INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38988, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ずっとむかしのこと。以前に。", "primary_collocate": null, "pronunciation": "かつて", "ipa": "katsɯte", "syllable_count": 3, "sentences": [{"text": "この町は嘗て港町だった。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "祖父は嘗て教師をしていた。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "嘗てここに古い寺があった。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "嘗ての友人に駅で会った。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "彼は嘗て有名な選手だった。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "嘗て見た映画をもう一度見た。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "この道は嘗て川だったそうだ。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "嘗ての校舎は今はもうない。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "私も嘗て同じ失敗をした。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}, {"text": "嘗て住んだ家を訪ねてみた。", "target_word": "嘗て", "complexity_tier": "T3", "furigana": "かつて", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘗ての", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 以前のある時期に、むかし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a88b6f8-76be-461d-bfbc-44bd3fe79298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EX