INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39008, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "誰かや何かを、もっとうまくいくように助けること。", "primary_collocate": null, "pronunciation": "あとおし", "ipa": "atooɕi", "syllable_count": 4, "sentences": [{"text": "先生の後押しで留学を決めた。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "母が私の夢を後押ししてくれた。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "友達の後押しが心強かった。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "兄の後押しを受けて挑戦した。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "みんなの後押しに感謝している。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "父は私の決心を後押しした。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "彼女の後押しがあって合格できた。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "後押ししてくれる人がいる。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "監督の後押しで試合に出た。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "祖母はいつも私を後押しする。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}], "morphological_forms": [{"form": "後押しする", "label": "派生"}, {"form": "後押しした", "label": "活用"}, {"form": "後押しして", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 人がうまくいくよう助けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '