INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39009, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が進んだり、実現したりするのを、支えたり励ましたりすること。", "primary_collocate": null, "pronunciation": "あとおし", "ipa": "atooɕi", "syllable_count": 4, "sentences": [{"text": "円安が輸出の後押しになった。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "市の後押しで祭りが復活した。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "新しい法律が改革を後押しした。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "住民の声が計画の後押しとなった。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "補助金が研究を後押ししている。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "雨が米の成長を後押しした。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "国の後押しで工事が進んだ。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "ネットの声が運動を後押しした。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "企業の後押しが大会を支えた。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}, {"text": "その発見は技術の後押しになる。", "target_word": "後押し", "complexity_tier": "T3", "furigana": "あとお", "sentence_source": "generated"}], "morphological_forms": [{"form": "後押しする", "label": "派生"}, {"form": "後押しされる", "label": "活用"}, {"form": "後押しして", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の進行や実現を支えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', t