INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39052, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外側だけが残って、中身がなくなったもの。", "primary_collocate": null, "pronunciation": "けいがい", "ipa": "keːgai", "syllable_count": 4, "sentences": [{"text": "焼けた家は形骸だけが残った。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "古い城の形骸が丘に立っている。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "虫の形骸が木の枝にあった。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "工場は今や形骸にすぎない。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "船の形骸が浜に打ち上げられた。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "形骸となった塔を見上げた。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "火事の後、店は形骸を残した。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "森の中に車の形骸があった。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "その建物の形骸は危ない。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "戦争で町は形骸だけになった。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}], "morphological_forms": [{"form": "形骸化", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 中身が失われ外側だけ残った物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a88b6f8-76be-461d-bfbc-44bd3fe79298') ON CONFLICT (sense_id, asset_type) D