INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39053, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本来の意味や実質を失い、外側の形式だけが残った状態。", "primary_collocate": null, "pronunciation": "けいがい", "ipa": "keːgai", "syllable_count": 4, "sentences": [{"text": "その規則は形骸にすぎない。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "会議は形骸だけが残っている。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "伝統が形骸になってしまった。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "この制度の形骸を見直そう。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "約束は形骸となって忘れられた。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "形骸だけの行事に意味はない。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "校則の多くは形骸と言える。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "選挙が形骸になってはいけない。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "その委員会は今や形骸だ。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}, {"text": "形骸を守るより中身が大事だ。", "target_word": "形骸", "complexity_tier": "T3", "furigana": "けいがい", "sentence_source": "generated"}], "morphological_forms": [{"form": "形骸化", "label": "派生"}, {"form": "形骸化する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 実質を失い形式だけ残った状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a88b6f8-76be-461d-bfbc-44bd3fe79298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39064, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだに着るもの。特に日本の伝統的な衣服。", "primary_collocate": "着る", "pronunciation": "きもの", "ipa": "kimono", "syllable_count": 3, "sentences": [{"text": "姉は正月に着物を着た。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "祖母の着物はとてもきれいだ。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物を着て写真を撮った。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "この着物は母からもらった。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物の女性が歩いていた。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物は一人で着るのが難しい。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "青い着物がよく似合っている。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物姿で祭りに出かけた。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "古い着物を大切にしている。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物を着ると背筋が伸びる。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "着", "label": "助数詞"}, {"form": "着物姿", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 日本の伝統的な衣服、着る物", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a88b6f8-76be-461d-bfbc-44bd3fe79298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38988, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘗て", "is_correct": true, "explanation": "正解：かつて。"}, {"text": "片手", "is_correct": false, "explanation": "かたてはかつてと一拍だけ違う別の語。"}, {"text": "勝手", "is_correct": false, "explanation": "かってはかつてと一拍だけ違う別の語。"}, {"text": "鬘", "is_correct": false, "explanation": "かつらはかつてと一拍だけ違う別の語。"}, {"text": "鰹", "is_correct": false, "explanation": "かつおはかつてと一拍だけ違う別の語。"}], "explanations": {"嘗て": "正解：かつて。", "片手": "かたてはかつてと一拍だけ違う別の語。", "勝手": "かってはかつてと一拍だけ違う別の語。", "鬘": "かつらはかつてと一拍だけ違う別の語。", "鰹": "かつおはかつてと一拍だけ違う別の語。"}, "sentence_index": null, "correct_answer": "嘗て"}, "level_3": {"options": [{"text": "嘗て", "is_correct": true, "explanation": "「以前は港町だった」という過去の状態を表す。"}, {"text": "やがて", "is_correct": false, "explanation": "やがては「しばらくして」の意で、「やがて港町だった」とは言わない。"}, {"text": "いずれ", "is_correct": false, "explanation": "いずれは未来を表し、過去形と合わない。"}, {"text": "今にも", "is_correct": false, "explanation": "今にもは直前の未来を表す。"}], "explanations": {"嘗て": "「以前は港町だった」という過去の状態を表す。", "やがて": "やがては「しばらくして」の意で、「やがて港町だった」とは言わない。", "いずれ": "いずれは未来を表し、過去形と合わない。", "今にも": "今にもは直前の未来を表す。"}, "sentence_index": 0, "correct_answer": "嘗て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は嘗て雨が降るだろう。", "explanation": "嘗ては過去を表すので未来の文に使えない。"}, {"text": "嘗てすぐに宿題を始めよう。", "explanation": "嘗ては過去の副詞で、これからの行動に使えない。"}, {"text": "彼は嘗て今ここにいる。", "explanation": "嘗てと「今」は同時に使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a968df-dbcd-4c6a-82fc-11ad4ad12d5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
