INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39008, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「夢を後押しする」と目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」はこの位置では不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」はこの位置では不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」はこの位置では不自然。"}], "correct_answer": "を", "explanations": {"を": "「夢を後押しする」と目的語を示す。", "に": "「に」はこの位置では不自然。", "で": "「で」はこの位置では不自然。", "が": "「が」はこの位置では不自然。"}, "error_tags": {"に": "case_confusion", "で": "case_confusion", "が": "subject_object"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "妨害", "is_correct": true, "explanation": "邪魔をすることで、後押しの反対。"}, {"text": "応援", "is_correct": false, "explanation": "応援は後押しと似た意味。"}, {"text": "支援", "is_correct": false, "explanation": "支援は後押しと似た意味。"}, {"text": "激励", "is_correct": false, "explanation": "激励は励ますことで似た意味。"}], "correct_answer": "妨害", "explanations": {"妨害": "邪魔をすることで、後押しの反対。", "応援": "応援は後押しと似た意味。", "支援": "支援は後押しと似た意味。", "激励": "激励は励ますことで似た意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0a968df-dbcd-4c6a-82fc-11ad4ad12d5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
