INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39065, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "日本の伝統的な衣服。帯をしめて着る。", "primary_collocate": null, "pronunciation": "きもの", "ipa": "kimono", "syllable_count": 3, "sentences": [{"text": "祖母は毎日着物を着ている。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物を着て写真を撮った。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "この着物はとても高い。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "姉の着物は赤くてきれいだ。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物で出かけるのは大変だ。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "正月に着物の人を見た。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "母が着物をたたんでいる。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "着物が一人で着られない。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "京都で着物を借りてみた。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}, {"text": "古い着物を大切にしている。", "target_word": "着物", "complexity_tier": "T3", "furigana": "きもの", "sentence_source": "generated"}], "morphological_forms": [{"form": "着", "label": "助数詞"}, {"form": "枚", "label": "助数詞"}, {"form": "着物姿", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 日本の伝統的な衣服のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-a006-ba680ad65037') ON C