INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35012, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "そうして。こうして。前のことを受けて話を続ける。", "primary_collocate": null, "pronunciation": "かくて", "ipa": "kakɯte", "syllable_count": 3, "sentences": [{"text": "斯くて二人は友達になった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて旅は終わった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて村に平和が戻った。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて新しい町ができた。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて彼は医者になった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて長い冬が過ぎていった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて物語は始まる。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて計画は成功した。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて王は国を去った。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて夏休みが終わった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "接続詞 | そうして、と話を続ける語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-a006-ba680ad65037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EX