INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "そういうわけで。前のことの結果を述べるときに使う。", "primary_collocate": null, "pronunciation": "かくて", "ipa": "kakɯte", "syllable_count": 3, "sentences": [{"text": "雨が続いた。斯くて米は不作だった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて試合は中止となった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "彼は毎日練習した。斯くて優勝した。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて会社はつぶれてしまった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "道が壊れた。斯くて村は孤立した。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて二人は別れることになった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて私たちは家を失った。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "薬が効いた。斯くて病は治った。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて店は閉まることになった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}, {"text": "斯くて約束は守られなかった。", "target_word": "斯くて", "complexity_tier": "T3", "furigana": "かく", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "接続詞 | 前を受けて結果を述べる語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-a006-ba680ad65037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content 