INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35034, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "回数を数えるときに使う言葉。「一度」「二度」など。", "primary_collocate": null, "pronunciation": "ど", "ipa": "do", "syllable_count": 1, "sentences": [{"text": "その映画は二度見た。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "京都へは三度行ったことがある。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "もう一度言ってください。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "何度も電話をかけた。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "彼には二度会った。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "この本は三度読んだ。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "一度だけ海で泳いだ。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "何度練習してもできない。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "今週は二度遅刻した。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "手を三度たたいてください。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}], "morphological_forms": [{"form": "一度", "label": "派生"}, {"form": "二度", "label": "派生"}, {"form": "何度", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 回数を数えるときの言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-a006-ba680ad65037') ON CONFLICT (sense_id, asset_type) DO UPDATE