INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35076, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "100年をひとまとまりとして数える単位。", "primary_collocate": null, "pronunciation": "せいき", "ipa": "seːki", "syllable_count": 3, "sentences": [{"text": "この寺は三世紀も前に建った。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "二世紀かけて町が育った。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "この木は一世紀以上生きている。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "数世紀の間、戦争が続いた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "その伝統は何世紀も続いている。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "この技術は一世紀前からある。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "橋は二世紀の間使われた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "城は数世紀前に壊れた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "言葉は何世紀もかけて変わる。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "その家は一世紀も残っている。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}], "morphological_forms": [{"form": "半世紀", "label": "派生"}, {"form": "世紀末", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 百年を一つとして数える単位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-a006-ba680ad65037') ON CONFLICT (sense_i