INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35077, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "100年ごとに区切った時代。1901年から2000年までが20世紀。", "primary_collocate": null, "pronunciation": "せいき", "ipa": "seːki", "syllable_count": 3, "sentences": [{"text": "私は21世紀に生まれた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "この絵は18世紀のものだ。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "20世紀には大きな戦争があった。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "今は21世紀だ。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "19世紀の町を写真で見た。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "この城は16世紀に建てられた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "世紀が変わる日に花火を見た。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "次の世紀はどうなるだろう。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "17世紀の本が見つかった。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}, {"text": "祖父は前の世紀に生まれた。", "target_word": "世紀", "complexity_tier": "T3", "furigana": "せいき", "sentence_source": "generated"}], "morphological_forms": [{"form": "今世紀", "label": "派生"}, {"form": "前世紀", "label": "派生"}, {"form": "世紀末", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 百年ごとに区切った時代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07136a18-006a-4f70-