INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39065, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着物", "is_correct": true, "explanation": "きもの。日本の伝統的な衣服。"}, {"text": "気持ち", "is_correct": false, "explanation": "きもち。三拍目「の」が「ち」に変わる一モーラ差。"}, {"text": "鋳物", "is_correct": false, "explanation": "いもの。一拍目「き」が「い」に変わる一モーラ差。"}, {"text": "鬼門", "is_correct": false, "explanation": "きもん。三拍目「の」が「ん」に変わる一モーラ差。"}], "explanations": {"着物": "きもの。日本の伝統的な衣服。", "気持ち": "きもち。三拍目「の」が「ち」に変わる一モーラ差。", "鋳物": "いもの。一拍目「き」が「い」に変わる一モーラ差。", "鬼門": "きもん。三拍目「の」が「ん」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "着物"}, "level_3": {"options": [{"text": "着物", "is_correct": true, "explanation": "伝統的な衣服で、「着ている」と自然に結びつく。"}, {"text": "帽子", "is_correct": false, "explanation": "連語：帽子は「かぶる」もので「着る」とは言わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "連語：眼鏡は「かける」もので「着る」とは言わない。"}, {"text": "靴", "is_correct": false, "explanation": "連語：靴は「はく」もので「着る」とは言わない。"}], "explanations": {"着物": "伝統的な衣服で、「着ている」と自然に結びつく。", "帽子": "連語：帽子は「かぶる」もので「着る」とは言わない。", "眼鏡": "連語：眼鏡は「かける」もので「着る」とは言わない。", "靴": "連語：靴は「はく」もので「着る」とは言わない。"}, "sentence_index": 0, "correct_answer": "着物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一冊の着物を買った。", "explanation": "助数詞の誤り：着物は「一着」「一枚」と数える。"}, {"text": "着物は着て祖母が出かけた。", "explanation": "助詞の混同：目的語には「を」を使う。"}, {"text": "明日、着物を着ていた。", "explanation": "アスペクトの誤り：未来の「明日」と「ていた」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
