INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39065, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「着る」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「着る」の目的語を主格では示せない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、ここでは非文になる。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、「着物で着て」は不自然。"}], "correct_answer": "を", "explanations": {"を": "他動詞「着る」の目的語を示す。", "が": "「着る」の目的語を主格では示せない。", "に": "着点を表し、ここでは非文になる。", "で": "手段を表し、「着物で着て」は不自然。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39065, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "着物", "is_correct": true, "explanation": "きもの。帯をしめて着る和服。"}, {"text": "干物", "is_correct": false, "explanation": "ひもの。最初の拍が「き」から「ひ」に変わる。"}, {"text": "獣", "is_correct": false, "explanation": "けもの。最初の拍が「き」から「け」に変わる。"}, {"text": "見物", "is_correct": false, "explanation": "みもの。最初の拍が「き」から「み」に変わる。"}], "explanations": {"着物": "きもの。帯をしめて着る和服。", "干物": "ひもの。最初の拍が「き」から「ひ」に変わる。", "獣": "けもの。最初の拍が「き」から「け」に変わる。", "見物": "みもの。最初の拍が「き」から「み」に変わる。"}, "sentence_index": null, "correct_answer": "着物"}, "level_3": {"options": [{"text": "着物", "is_correct": true, "explanation": "「たたむ」対象として自然な衣服。"}, {"text": "ご飯", "is_correct": false, "explanation": "意味：ご飯はたたむことができない。"}, {"text": "皿", "is_correct": false, "explanation": "意味：皿はたたむことができない。"}, {"text": "お茶", "is_correct": false, "explanation": "意味：お茶はたたむことができない。"}], "explanations": {"着物": "「たたむ」対象として自然な衣服。", "ご飯": "意味：ご飯はたたむことができない。", "皿": "意味：皿はたたむことができない。", "お茶": "意味：お茶はたたむことができない。"}, "sentence_index": 6, "correct_answer": "着物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い着物を一匹もらった。", "explanation": "助数詞の誤り：着物は「一枚」「一着」と数える。"}, {"text": "着物を姉に着ている。", "explanation": "助詞の混同：「姉に着ている」は誤り。「姉が着物を着ている」が正しい。"}, {"text": "明日、着物を着た。", "explanation": "時制の誤り：未来の「明日」と過去形「着た」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39065, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は着物をはいて出かけた。", "corrected_sentence": "母は着物を着て出かけた。", "error_description": "「はく」は靴やズボンに使う。着物は「着る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
