INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35012, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "かくて。こうして、と話を続ける。"}, {"text": "各地", "is_correct": false, "explanation": "かくち。三拍目「て」が「ち」に変わる一モーラ差。"}, {"text": "覚悟", "is_correct": false, "explanation": "かくご。三拍目「て」が「ご」に変わる一モーラ差。"}, {"text": "勝手", "is_correct": false, "explanation": "かって。二拍目「く」が促音「っ」に変わる。"}, {"text": "各位", "is_correct": false, "explanation": "かくい。三拍目「て」が「い」に変わる一モーラ差。"}], "explanations": {"斯くて": "かくて。こうして、と話を続ける。", "各地": "かくち。三拍目「て」が「ち」に変わる一モーラ差。", "覚悟": "かくご。三拍目「て」が「ご」に変わる一モーラ差。", "勝手": "かって。二拍目「く」が促音「っ」に変わる。", "各位": "かくい。三拍目「て」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "斯くて"}, "level_3": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "前のことを受けて、こうして話が続く。"}, {"text": "もしくは", "is_correct": false, "explanation": "意味：選択を表す語で、文頭で出来事を述べられない。"}, {"text": "たとえば", "is_correct": false, "explanation": "意味：例を挙げる語で、結果の流れを表さない。"}, {"text": "なぜなら", "is_correct": false, "explanation": "意味：理由を述べる語で、後に「から」が必要。"}], "explanations": {"斯くて": "前のことを受けて、こうして話が続く。", "もしくは": "意味：選択を表す語で、文頭で出来事を述べられない。", "たとえば": "意味：例を挙げる語で、結果の流れを表さない。", "なぜなら": "意味：理由を述べる語で、後に「から」が必要。"}, "sentence_index": 0, "correct_answer": "斯くて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は斯くて雨が降るだろう。", "explanation": "語順・係り受けの誤り：斯くては前の話を受けて文頭に置く。"}, {"text": "斯くて、だから町ができた。", "explanation": "語の重複：斯くてと「だから」を重ねて使わない。"}, {"text": "斯くて町ができている前だった。", "explanation": "活用・アスペクトの誤り：「できている前」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
