INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35012, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "かくて。こうして、と話を続ける。"}, {"text": "角煮", "is_correct": false, "explanation": "かくに。三拍目「て」が「に」に変わる。"}, {"text": "書き手", "is_correct": false, "explanation": "かきて。二拍目「く」が「き」に変わる。"}, {"text": "隠し", "is_correct": false, "explanation": "かくし。三拍目「て」が「し」に変わる。"}, {"text": "各地", "is_correct": false, "explanation": "かくち。三拍目「て」が「ち」に変わる。"}], "explanations": {"斯くて": "かくて。こうして、と話を続ける。", "角煮": "かくに。三拍目「て」が「に」に変わる。", "書き手": "かきて。二拍目「く」が「き」に変わる。", "隠し": "かくし。三拍目「て」が「し」に変わる。", "各地": "かくち。三拍目「て」が「ち」に変わる。"}, "sentence_index": null, "correct_answer": "斯くて"}, "level_3": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "それまでの出来事を受け、物語が始まる流れを表す。"}, {"text": "なぜなら", "is_correct": false, "explanation": "意味：理由を述べる語で、後に「から」が必要。"}, {"text": "または", "is_correct": false, "explanation": "意味：選択を表し、文頭で続きを述べられない。"}, {"text": "もしくは", "is_correct": false, "explanation": "意味：選択を表し、文頭で続きを述べられない。"}], "explanations": {"斯くて": "それまでの出来事を受け、物語が始まる流れを表す。", "なぜなら": "意味：理由を述べる語で、後に「から」が必要。", "または": "意味：選択を表し、文頭で続きを述べられない。", "もしくは": "意味：選択を表し、文頭で続きを述べられない。"}, "sentence_index": 6, "correct_answer": "斯くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みが斯くて終わるか。", "explanation": "語順の誤り：斯くては文の頭で前の話を受ける。"}, {"text": "斯くて夏休みが終わってある。", "explanation": "アスペクトの誤り：「終わってある」は誤り。"}, {"text": "斯くて夏休みは来週から始まった。", "explanation": "時の誤り：「来週」と過去形「始まった」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
