INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "かくて。そういうわけで、と結果を述べる。"}, {"text": "各地", "is_correct": false, "explanation": "かくち。三拍目「て」が「ち」に変わる一モーラ差。"}, {"text": "覚悟", "is_correct": false, "explanation": "かくご。三拍目「て」が「ご」に変わる一モーラ差。"}, {"text": "勝手", "is_correct": false, "explanation": "かって。二拍目「く」が促音「っ」に変わる。"}, {"text": "各位", "is_correct": false, "explanation": "かくい。三拍目「て」が「い」に変わる一モーラ差。"}], "explanations": {"斯くて": "かくて。そういうわけで、と結果を述べる。", "各地": "かくち。三拍目「て」が「ち」に変わる一モーラ差。", "覚悟": "かくご。三拍目「て」が「ご」に変わる一モーラ差。", "勝手": "かって。二拍目「く」が促音「っ」に変わる。", "各位": "かくい。三拍目「て」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "斯くて"}, "level_3": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "雨が続いた結果として不作を述べる。"}, {"text": "それでも", "is_correct": false, "explanation": "意味：逆接で、結果を素直に述べない。"}, {"text": "さて", "is_correct": false, "explanation": "意味：話題を変える語で結果を述べない。"}, {"text": "ところが", "is_correct": false, "explanation": "意味：予想と反対のことを述べる語で、自然な結果を述べない。"}], "explanations": {"斯くて": "雨が続いた結果として不作を述べる。", "それでも": "意味：逆接で、結果を素直に述べない。", "さて": "意味：話題を変える語で結果を述べない。", "ところが": "意味：予想と反対のことを述べる語で、自然な結果を述べない。"}, "sentence_index": 0, "correct_answer": "斯くて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は斯くてつぶれるでしょうか。", "explanation": "語順の誤り：斯くては前の出来事を受けて文頭に置く。"}, {"text": "斯くて会社をつぶれてしまった。", "explanation": "助詞の混同：「つぶれる」は自動詞なので「が／は」を使う。"}, {"text": "斯くて、明日会社はつぶれてしまった。", "explanation": "時の誤り：「明日」と「てしまった」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が続いた。斯くて米は豊作だった。", "corrected_sentence": "雨が続いた。斯くて米は不作だった。", "error_description": "雨が続いた結果として「豊作」は合わない。斯くては結果を述べる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "かくて。そういうわけで、と結果を述べる。"}, {"text": "角煮", "is_correct": false, "explanation": "かくに。三拍目「て」が「に」に変わる。"}, {"text": "書き手", "is_correct": false, "explanation": "かきて。二拍目「く」が「き」に変わる。"}, {"text": "隠し", "is_correct": false, "explanation": "かくし。三拍目「て」が「し」に変わる。"}, {"text": "各地", "is_correct": false, "explanation": "かくち。三拍目「て」が「ち」に変わる。"}], "explanations": {"斯くて": "かくて。そういうわけで、と結果を述べる。", "角煮": "かくに。三拍目「て」が「に」に変わる。", "書き手": "かきて。二拍目「く」が「き」に変わる。", "隠し": "かくし。三拍目「て」が「し」に変わる。", "各地": "かくち。三拍目「て」が「ち」に変わる。"}, "sentence_index": null, "correct_answer": "斯くて"}, "level_3": {"options": [{"text": "斯くて", "is_correct": true, "explanation": "前の出来事の結果、家を失ったことを述べる。"}, {"text": "ただし", "is_correct": false, "explanation": "意味：条件を付け加える語で結果を述べない。"}, {"text": "例えば", "is_correct": false, "explanation": "意味：例を挙げる語で結果を述べない。"}, {"text": "もしくは", "is_correct": false, "explanation": "意味：選択を表し、文が成り立たない。"}], "explanations": {"斯くて": "前の出来事の結果、家を失ったことを述べる。", "ただし": "意味：条件を付け加える語で結果を述べない。", "例えば": "意味：例を挙げる語で結果を述べない。", "もしくは": "意味：選択を表し、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "斯くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "約束は守られなかったか、斯くて。", "explanation": "語順の誤り：斯くては文の初めに置く。"}, {"text": "斯くて約束は守らられなかった。", "explanation": "活用の誤り：受身は「守られる」で、「守らられる」とは言わない。"}, {"text": "斯くて約束は守られないでいた明日。", "explanation": "アスペクトと語順の誤り：「明日」の位置と時制が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "斯くて私たちは家を失うなら。", "corrected_sentence": "斯くて私たちは家を失った。", "error_description": "斯くては結果を述べる語で、仮定の「なら」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
