INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35034, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "ど。回数を数える言葉。"}, {"text": "戸", "is_correct": false, "explanation": "と。清濁の対立（ど↔と）。"}, {"text": "胴", "is_correct": false, "explanation": "どう。長短母音の対立。"}, {"text": "碁", "is_correct": false, "explanation": "ご。子音が違う一モーラ差。"}, {"text": "野", "is_correct": false, "explanation": "の。子音が違う一モーラ差。"}], "explanations": {"度": "ど。回数を数える言葉。", "戸": "と。清濁の対立（ど↔と）。", "胴": "どう。長短母音の対立。", "碁": "ご。子音が違う一モーラ差。", "野": "の。子音が違う一モーラ差。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "度", "is_correct": true, "explanation": "回数を数え、「二度見た」と言う。"}, {"text": "冊", "is_correct": false, "explanation": "意味：本を数える助数詞で、映画には使わない。"}, {"text": "枚", "is_correct": false, "explanation": "意味：紙などを数える助数詞で、見る回数ではない。"}, {"text": "台", "is_correct": false, "explanation": "意味：機械を数える助数詞で、回数ではない。"}], "explanations": {"度": "回数を数え、「二度見た」と言う。", "冊": "意味：本を数える助数詞で、映画には使わない。", "枚": "意味：紙などを数える助数詞で、見る回数ではない。", "台": "意味：機械を数える助数詞で、回数ではない。"}, "sentence_index": 0, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "何度の電話をかけた。", "explanation": "助詞の混同：「何度も」が正しい。"}, {"text": "電話を何度かけていた明日。", "explanation": "語順とアスペクトの誤り。"}, {"text": "一度の犬を飼っている。", "explanation": "助数詞の誤り：犬は「一匹」と数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この本は三度に読んだ。", "corrected_sentence": "この本は三度読んだ。", "error_description": "回数の「三度」には助詞「に」を付けない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
