INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35034, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "ど。回数を表す。"}, {"text": "帆", "is_correct": false, "explanation": "ほ。母音は同じで子音だけが違う一モーラ差。"}, {"text": "炉", "is_correct": false, "explanation": "ろ。母音は同じで子音だけが違う一モーラ差。"}, {"text": "図", "is_correct": false, "explanation": "ず。子音も母音も違う一モーラ差。"}], "explanations": {"度": "ど。回数を表す。", "帆": "ほ。母音は同じで子音だけが違う一モーラ差。", "炉": "ろ。母音は同じで子音だけが違う一モーラ差。", "図": "ず。子音も母音も違う一モーラ差。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "度", "is_correct": true, "explanation": "「一度だけ」で一回だけという回数を表す。"}, {"text": "本", "is_correct": false, "explanation": "意味：細長い物を数え、泳いだ回数ではない。"}, {"text": "匹", "is_correct": false, "explanation": "意味：動物を数える助数詞。"}, {"text": "個", "is_correct": false, "explanation": "意味：物を数える助数詞で、回数ではない。"}], "explanations": {"度": "「一度だけ」で一回だけという回数を表す。", "本": "意味：細長い物を数え、泳いだ回数ではない。", "匹": "意味：動物を数える助数詞。", "個": "意味：物を数える助数詞で、回数ではない。"}, "sentence_index": 6, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手を三度にたたいた。", "explanation": "助詞の混同：回数に「に」は付けない。"}, {"text": "三度の本を買った。", "explanation": "助数詞の誤り：本は「三冊」と数える。"}, {"text": "手を三度たたいている昨日。", "explanation": "語順・アスペクトの誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一度は海で泳ぐだった。", "corrected_sentence": "一度は海で泳いだ。", "error_description": "「泳ぐだった」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
