INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35076, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世紀", "is_correct": true, "explanation": "せいき。百年をひとまとまりとする。"}, {"text": "正義", "is_correct": false, "explanation": "せいぎ。き→ぎの清濁の対立。"}, {"text": "生徒", "is_correct": false, "explanation": "せいと。き→との一モーラ差。"}, {"text": "政府", "is_correct": false, "explanation": "せいふ。き→ふの一モーラ差。"}, {"text": "成果", "is_correct": false, "explanation": "せいか。き→かの一モーラ差。"}], "explanations": {"世紀": "せいき。百年をひとまとまりとする。", "正義": "せいぎ。き→ぎの清濁の対立。", "生徒": "せいと。き→との一モーラ差。", "政府": "せいふ。き→ふの一モーラ差。", "成果": "せいか。き→かの一モーラ差。"}, "sentence_index": null, "correct_answer": "世紀"}, "level_3": {"options": [{"text": "世紀", "is_correct": true, "explanation": "百年単位で「三世紀前」と言う。"}, {"text": "時間", "is_correct": false, "explanation": "意味：「三時間も前に建った」では寺の古さに合わない。"}, {"text": "分", "is_correct": false, "explanation": "意味：寺が三分前に建つことはない。"}, {"text": "秒", "is_correct": false, "explanation": "意味：寺が三秒前に建つことはない。"}], "explanations": {"世紀": "百年単位で「三世紀前」と言う。", "時間": "意味：「三時間も前に建った」では寺の古さに合わない。", "分": "意味：寺が三分前に建つことはない。", "秒": "意味：寺が三秒前に建つことはない。"}, "sentence_index": 0, "correct_answer": "世紀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一冊の世紀が過ぎた。", "explanation": "助数詞の誤り：世紀に「冊」は使わない。"}, {"text": "数世紀を戦争が続いた。", "explanation": "助詞の混同：「数世紀の間」または「数世紀も」が自然。"}, {"text": "数世紀の間、戦争が続いている昨日。", "explanation": "語順・アスペクトの誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35076, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この寺は三世紀も前に建つだろう。", "corrected_sentence": "この寺は三世紀も前に建った。", "error_description": "過去の「三世紀も前」に推量の「だろう」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cfe3380-ab85-4562-bf1b-fe9c21d48a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
