INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39154, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "海の近くの土地や地域のこと。", "primary_collocate": null, "pronunciation": "えんがん", "ipa": "eŋɡaɴ", "syllable_count": 4, "sentences": [{"text": "沿岸には小さな町が多い。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん ちい まち おお", "sentence_source": "generated"}, {"text": "台風が沿岸に近づいている。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "たいふう えんがん ちか", "sentence_source": "generated"}, {"text": "沿岸の村では魚がよくとれる。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん むら さかな", "sentence_source": "generated"}, {"text": "私たちは沿岸を車で走った。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "わたし えんがん くるま はし", "sentence_source": "generated"}, {"text": "この沿岸は冬に風が強い。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん ふゆ かぜ つよ", "sentence_source": "generated"}, {"text": "沿岸に大雨が降った。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん おおあめ ふ", "sentence_source": "generated"}, {"text": "祖父は沿岸の町に住んでいる。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "そふ えんがん まち す", "sentence_source": "generated"}, {"text": "沿岸から島が見える。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん しま み", "sentence_source": "generated"}, {"text": "津波が沿岸に来た。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "つなみ えんがん き", "sentence_source": "generated"}, {"text": "沿岸の道から海が見える。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん みち うみ み", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿岸部", "label": "派生"}, {"form": "沿岸地域", "label": "派生"}, {"form": "沿岸警備", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 海のそばの土地や地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-