INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "海に接している陸地の部分。海岸沿いの地域。", "primary_collocate": null, "pronunciation": "えんがん", "ipa": "eŋɡaɴ", "syllable_count": 4, "sentences": [{"text": "沿岸ではよく漁業が行われる。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん ぎょぎょう おこな", "sentence_source": "generated"}, {"text": "船は沿岸に沿って進んだ。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "ふね えんがん そ すす", "sentence_source": "generated"}, {"text": "沿岸の住民に注意が出された。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん じゅうみん ちゅうい だ", "sentence_source": "generated"}, {"text": "高い波が沿岸に来た。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "たか なみ えんがん き", "sentence_source": "generated"}, {"text": "この国は沿岸が長い。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "くに えんがん なが", "sentence_source": "generated"}, {"text": "沿岸の工場が新しくなった。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん こうじょう あたら", "sentence_source": "generated"}, {"text": "鳥が沿岸を飛んでいる。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "とり えんがん と", "sentence_source": "generated"}, {"text": "沿岸の水がきれいになった。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "えんがん みず", "sentence_source": "generated"}, {"text": "父は沿岸で働いている。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "ちち えんがん はたら", "sentence_source": "generated"}, {"text": "夏は沿岸に人が集まる。", "target_word": "沿岸", "complexity_tier": "T3", "furigana": "なつ えんがん ひと あつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿岸部", "label": "派生"}, {"form": "沿岸地域", "label": "派生"}, {"form": "沿岸警備", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 海に接する陸地の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 