INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39154, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正解。対象語の読みそのもの。"}, {"text": "縁側", "is_correct": false, "explanation": "読みは「えんがわ」。最後の「ん」が「わ」に変わる一モーラ差。"}, {"text": "縁談", "is_correct": false, "explanation": "読みは「えんだん」。「が」が「だ」に変わる一モーラ差。"}, {"text": "円環", "is_correct": false, "explanation": "読みは「えんかん」。「が」が「か」に変わる清濁の差。"}, {"text": "塩害", "is_correct": false, "explanation": "読みは「えんがい」。最後の「ん」が「い」に変わる一モーラ差。"}, {"text": "演算", "is_correct": false, "explanation": "読みは「えんざん」。「が」が「ざ」に変わる一モーラ差。"}], "explanations": {"沿岸": "正解。対象語の読みそのもの。", "縁側": "読みは「えんがわ」。最後の「ん」が「わ」に変わる一モーラ差。", "縁談": "読みは「えんだん」。「が」が「だ」に変わる一モーラ差。", "円環": "読みは「えんかん」。「が」が「か」に変わる清濁の差。", "塩害": "読みは「えんがい」。最後の「ん」が「い」に変わる一モーラ差。", "演算": "読みは「えんざん」。「が」が「ざ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "沿岸"}, "level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "意味：海の近くの地域には小さな町が多い。"}, {"text": "天井", "is_correct": false, "explanation": "意味：天井に町があるというのは不可能。"}, {"text": "机", "is_correct": false, "explanation": "意味：机の上に町はない。"}, {"text": "宿題", "is_correct": false, "explanation": "連語：「宿題には町が多い」は結びつかない。"}], "explanations": {"沿岸": "意味：海の近くの地域には小さな町が多い。", "天井": "意味：天井に町があるというのは不可能。", "机": "意味：机の上に町はない。", "宿題": "連語：「宿題には町が多い」は結びつかない。"}, "sentence_index": 0, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沿岸が一冊ある。", "explanation": "助数詞の誤り：土地を「冊」で数えることはない。"}, {"text": "私たちは沿岸を車で走るた。", "explanation": "活用の誤り：「走る」に「た」は続かない。"}, {"text": "沿岸は私たちを車で走った。", "explanation": "助詞の混同：主語と場所が入れ替わり意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.pr