INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39155, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正解。対象語の読みそのもの。"}, {"text": "円盤", "is_correct": false, "explanation": "読みは「えんばん」。「が」が「ば」に変わる一モーラ差。"}, {"text": "延期", "is_correct": false, "explanation": "読みは「えんき」。後半が「き」に変わる差。"}, {"text": "遠泳", "is_correct": false, "explanation": "読みは「えんえい」。後半が「えい」に変わる差。"}, {"text": "縁談", "is_correct": false, "explanation": "読みは「えんだん」。「が」が「だ」に変わる一モーラ差。"}, {"text": "塩害", "is_correct": false, "explanation": "読みは「えんがい」。最後の「ん」が「い」に変わる一モーラ差。"}], "explanations": {"沿岸": "正解。対象語の読みそのもの。", "円盤": "読みは「えんばん」。「が」が「ば」に変わる一モーラ差。", "延期": "読みは「えんき」。後半が「き」に変わる差。", "遠泳": "読みは「えんえい」。後半が「えい」に変わる差。", "縁談": "読みは「えんだん」。「が」が「だ」に変わる一モーラ差。", "塩害": "読みは「えんがい」。最後の「ん」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "沿岸"}, "level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "意味：鳥が海辺の上を飛んでいる。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：宿題を飛ぶことはない。"}, {"text": "財布", "is_correct": false, "explanation": "意味：財布を飛ぶことはできない。"}, {"text": "名前", "is_correct": false, "explanation": "連語：「名前を飛ぶ」は結びつかない。"}], "explanations": {"沿岸": "意味：鳥が海辺の上を飛んでいる。", "宿題": "意味：宿題を飛ぶことはない。", "財布": "意味：財布を飛ぶことはできない。", "名前": "連語：「名前を飛ぶ」は結びつかない。"}, "sentence_index": 6, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏は沿岸を人が集まる。", "explanation": "助詞の混同：集まる場所は「に」で示す。"}, {"text": "沿岸が二枚ある。", "explanation": "助数詞の誤り：土地を「枚」で数えない。"}, {"text": "夏は沿岸に人が集まるた。", "explanation": "活用の誤り：「集まる」に「た」は続かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, valida