INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39193, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "銀杏", "is_correct": true, "explanation": "正解。対象語の読みそのもの。"}, {"text": "銀山", "is_correct": false, "explanation": "読みは「ぎんざん」。「な」が「ざ」に変わる一モーラ差。"}, {"text": "銀盤", "is_correct": false, "explanation": "読みは「ぎんばん」。「な」が「ば」に変わる一モーラ差。"}, {"text": "銀行", "is_correct": false, "explanation": "読みは「ぎんこう」。後半が「こう」に変わる差。"}], "explanations": {"銀杏": "正解。対象語の読みそのもの。", "銀山": "読みは「ぎんざん」。「な」が「ざ」に変わる一モーラ差。", "銀盤": "読みは「ぎんばん」。「な」が「ば」に変わる一モーラ差。", "銀行": "読みは「ぎんこう」。後半が「こう」に変わる差。"}, "sentence_index": null, "correct_answer": "銀杏"}, "level_3": {"options": [{"text": "銀杏", "is_correct": true, "explanation": "意味：秋にイチョウの実を拾いに行った。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：宿題を拾いに行くことはない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は拾えない。"}, {"text": "音楽", "is_correct": false, "explanation": "連語：「音楽を拾う」は結びつかない。"}], "explanations": {"銀杏": "意味：秋にイチョウの実を拾いに行った。", "宿題": "意味：宿題を拾いに行くことはない。", "天気": "意味：天気は拾えない。", "音楽": "連語：「音楽を拾う」は結びつかない。"}, "sentence_index": 0, "correct_answer": "銀杏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "茶わん蒸しを銀杏が入っている。", "explanation": "助詞の混同：入っている場所は「に」で示す。"}, {"text": "銀杏が二匹入っている。", "explanation": "助数詞の誤り：実は「粒」や「個」で数える。"}, {"text": "茶わん蒸しに銀杏が入ったている。", "explanation": "活用の誤り：「入っている」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
