INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39193, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「焼く」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "この位置では主語になり、母が主語なので非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、焼く対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「焼く」の目的語を表す。", "が": "この位置では主語になり、母が主語なので非文。", "に": "着点を表し、目的語にならない。", "へ": "方向を表し、焼く対象にならない。"}, "error_tags": {"が": "topic_vs_subject", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39193, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "銀杏", "is_correct": true, "explanation": "正解。対象語の読みそのもの。"}, {"text": "銀河", "is_correct": false, "explanation": "読みは「ぎんが」。後半が「が」に変わる差。"}, {"text": "禁断", "is_correct": false, "explanation": "読みは「きんだん」。「ぎ」が「き」、「な」が「だ」に変わる差。"}, {"text": "銀幕", "is_correct": false, "explanation": "読みは「ぎんまく」。後半が「まく」に変わる差。"}], "explanations": {"銀杏": "正解。対象語の読みそのもの。", "銀河": "読みは「ぎんが」。後半が「が」に変わる差。", "禁断": "読みは「きんだん」。「ぎ」が「き」、「な」が「だ」に変わる差。", "銀幕": "読みは「ぎんまく」。後半が「まく」に変わる差。"}, "sentence_index": null, "correct_answer": "銀杏"}, "level_3": {"options": [{"text": "銀杏", "is_correct": true, "explanation": "意味：店でイチョウの実を買った。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は買えない。"}, {"text": "空", "is_correct": false, "explanation": "意味：空を店で買うことはない。"}, {"text": "名前", "is_correct": false, "explanation": "連語：「名前を買う」は結びつかない。"}], "explanations": {"銀杏": "意味：店でイチョウの実を買った。", "天気": "意味：天気は買えない。", "空": "意味：空を店で買うことはない。", "名前": "連語：「名前を買う」は結びつかない。"}, "sentence_index": 6, "correct_answer": "銀杏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は銀杏で好きだ。", "explanation": "助詞の混同：「好きだ」の対象は「が」で示す。"}, {"text": "銀杏が三台ある。", "explanation": "助数詞の誤り：実は「粒」や「個」で数える。"}, {"text": "祖母は銀杏が好きだた。", "explanation": "活用の誤り：「好きだ」に「た」は続かない（「好きだった」）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
