INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39216, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毎週", "is_correct": true, "explanation": "正解。対象語の読みそのもの。"}, {"text": "回収", "is_correct": false, "explanation": "読みは「かいしゅう」。「ま」が「か」に変わる一モーラ差。"}, {"text": "買収", "is_correct": false, "explanation": "読みは「ばいしゅう」。「ま」が「ば」に変わる一モーラ差。"}, {"text": "大衆", "is_correct": false, "explanation": "読みは「たいしゅう」。「ま」が「た」に変わる一モーラ差。"}, {"text": "最終", "is_correct": false, "explanation": "読みは「さいしゅう」。「ま」が「さ」に変わる一モーラ差。"}], "explanations": {"毎週": "正解。対象語の読みそのもの。", "回収": "読みは「かいしゅう」。「ま」が「か」に変わる一モーラ差。", "買収": "読みは「ばいしゅう」。「ま」が「ば」に変わる一モーラ差。", "大衆": "読みは「たいしゅう」。「ま」が「た」に変わる一モーラ差。", "最終": "読みは「さいしゅう」。「ま」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "毎週"}, "level_3": {"options": [{"text": "毎週", "is_correct": true, "explanation": "意味：一週間ごとに日曜日にテニスをする。"}, {"text": "毎朝", "is_correct": false, "explanation": "意味：「毎朝、日曜日に」は頻度が矛盾する。"}, {"text": "昨日", "is_correct": false, "explanation": "アスペクト：「昨日」と現在形「する」が合わない。"}, {"text": "毎晩", "is_correct": false, "explanation": "意味：「毎晩、日曜日に」は頻度が矛盾する。"}], "explanations": {"毎週": "意味：一週間ごとに日曜日にテニスをする。", "毎朝": "意味：「毎朝、日曜日に」は頻度が矛盾する。", "昨日": "アスペクト：「昨日」と現在形「する」が合わない。", "毎晩": "意味：「毎晩、日曜日に」は頻度が矛盾する。"}, "sentence_index": 0, "correct_answer": "毎週"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は毎週祖母を電話している。", "explanation": "助詞の混同：電話の相手は「に」で示す。"}, {"text": "兄は毎週祖母に昨日電話した。", "explanation": "語順・時の誤り：「毎週」と「昨日」が同時に使えない。"}, {"text": "兄は毎週祖母に電話したている。", "explanation": "活用の誤り：「電話している」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3394614-dcc0-4940-8818-62c60704a44d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
