INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41258, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気を治すために飲んだり塗ったりするもの。薬。", "primary_collocate": null, "pronunciation": "やくぶつ", "ipa": "jakɯbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "医者は新しい薬物を使った。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "この薬物は熱を下げる。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物の量に気をつけている。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "病院で薬物をもらった。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物で痛みが軽くなった。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "子どもには強い薬物を使わない。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "この薬物は一日三回飲む。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "彼は薬物に頼らず治した。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物が効いて、よく眠れた。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "古い薬物は捨ててください。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "薬物療法", "label": "派生"}, {"form": "薬物治療", "label": "派生"}, {"form": "錠", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 病気を治すために使う薬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93fc5102-787e-4862