INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41259, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体に作用する化学物質。特に、乱用されると害になる薬。", "primary_collocate": null, "pronunciation": "やくぶつ", "ipa": "jakɯbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "薬物の乱用は体を壊す。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "選手は薬物の検査を受けた。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "警察が違法な薬物を見つけた。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物は絶対に使ってはいけない。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "学校で薬物の危険を学んだ。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "彼は薬物をやめることができた。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物に手を出すのは危ない。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "この薬物は法律で禁止されている。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "薬物で人生を失う人もいる。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}, {"text": "若者を薬物から守りたい。", "target_word": "薬物", "complexity_tier": "T3", "furigana": "やくぶつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "薬物乱用", "label": "派生"}, {"form": "薬物依存", "label": "派生"}, {"form": "薬物検査", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 体に作用し乱用で害となる化学物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL,