INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41256, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一つ一つ、別々にすること。", "primary_collocate": null, "pronunciation": "こべつ", "ipa": "kobetsɯ", "syllable_count": 3, "sentences": [{"text": "先生が個別に話を聞いた。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "質問には個別に答えます。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "今日は個別の面談がある。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "個別の相談も受けています。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "塾で個別の指導を受けている。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "荷物は個別に包んでください。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "問題を個別に考えてみよう。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "個別の事情は考えない。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "料金は個別に払ってください。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}, {"text": "全員に個別の連絡をした。", "target_word": "個別", "complexity_tier": "T3", "furigana": "こべつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "個別に", "label": "派生"}, {"form": "個別的", "label": "派生"}, {"form": "個別指導", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一つ一つを別々に扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93fc5102-787e-4862-b3e3-035c69a1a317')