INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39220, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日", "is_correct": true, "explanation": "「ひ」。空にかがやく太陽。"}, {"text": "血", "is_correct": false, "explanation": "「ち」。ひ→ちの一モーラ差。体を流れる赤い液。"}, {"text": "手", "is_correct": false, "explanation": "「て」。ひ→ての一モーラ差。体の一部。"}, {"text": "目", "is_correct": false, "explanation": "「め」。ひ→めの一モーラ差。見るための器官。"}, {"text": "木", "is_correct": false, "explanation": "「き」。ひ→きの一モーラ差。植物。"}], "explanations": {"日": "「ひ」。空にかがやく太陽。", "血": "「ち」。ひ→ちの一モーラ差。体を流れる赤い液。", "手": "「て」。ひ→ての一モーラ差。体の一部。", "目": "「め」。ひ→めの一モーラ差。見るための器官。", "木": "「き」。ひ→きの一モーラ差。植物。"}, "sentence_index": null, "correct_answer": "日"}, "level_3": {"options": [{"text": "日", "is_correct": true, "explanation": "太陽が東から昇るので正しい。"}, {"text": "海", "is_correct": false, "explanation": "意味：海は空から昇るものではない。"}, {"text": "雨", "is_correct": false, "explanation": "連語：雨は「昇る」ものではない。"}, {"text": "風", "is_correct": false, "explanation": "連語：風は「昇る」と言わない。"}], "explanations": {"日": "太陽が東から昇るので正しい。", "海": "意味：海は空から昇るものではない。", "雨": "連語：雨は「昇る」ものではない。", "風": "連語：風は「昇る」と言わない。"}, "sentence_index": 0, "correct_answer": "日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日を窓から差してきた。", "explanation": "助詞の混同：「差す」は自動詞なので「日が」とする。"}, {"text": "窓から一冊の日が差してきた。", "explanation": "助数詞の誤り：太陽に「冊」は使わない。"}, {"text": "窓から日が差していった昨日。", "explanation": "語順の誤り：時の語「昨日」は文頭に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ef60f0-cf2f-42ff-bf57-1d01856f6eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
