INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39220, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "日", "is_correct": true, "explanation": "「ひ」。太陽。"}, {"text": "歯", "is_correct": false, "explanation": "「は」。ひ→はの母音一モーラ差。口の中の歯。"}, {"text": "毛", "is_correct": false, "explanation": "「け」。ひ→けの一モーラ差。体に生える毛。"}, {"text": "実", "is_correct": false, "explanation": "「み」。ひ→みの一モーラ差。木の実。"}, {"text": "帆", "is_correct": false, "explanation": "「ほ」。ひ→ほの母音一モーラ差。船の帆。"}], "explanations": {"日": "「ひ」。太陽。", "歯": "「は」。ひ→はの母音一モーラ差。口の中の歯。", "毛": "「け」。ひ→けの一モーラ差。体に生える毛。", "実": "「み」。ひ→みの一モーラ差。木の実。", "帆": "「ほ」。ひ→ほの母音一モーラ差。船の帆。"}, "sentence_index": null, "correct_answer": "日"}, "level_3": {"options": [{"text": "日", "is_correct": true, "explanation": "強い太陽の光で肌が焼けるので正しい。"}, {"text": "本", "is_correct": false, "explanation": "意味：本に焼けることはない。"}, {"text": "水", "is_correct": false, "explanation": "連語：「水に焼ける」とは言わない。"}, {"text": "机", "is_correct": false, "explanation": "意味：机に焼けて顔が赤くなることはない。"}], "explanations": {"日": "強い太陽の光で肌が焼けるので正しい。", "本": "意味：本に焼けることはない。", "水": "連語：「水に焼ける」とは言わない。", "机": "意味：机に焼けて顔が赤くなることはない。"}, "sentence_index": 6, "correct_answer": "日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日が当たる部屋で本を読んでいた明日。", "explanation": "アスペクトと語順の誤り：「明日」と過去の「ていた」が合わない。"}, {"text": "日に当たる部屋を本を読む。", "explanation": "助詞の混同：場所は「で」で表す。"}, {"text": "二枚の日が当たる部屋で本を読む。", "explanation": "助数詞の誤り：太陽は「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ef60f0-cf2f-42ff-bf57-1d01856f6eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
