INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39221, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日", "is_correct": true, "explanation": "「ひ」。一日。"}, {"text": "血", "is_correct": false, "explanation": "「ち」。ひ→ちの一モーラ差。体を流れる液。"}, {"text": "気", "is_correct": false, "explanation": "「き」。ひ→きの一モーラ差。気持ち。"}, {"text": "葉", "is_correct": false, "explanation": "「は」。ひ→はの母音一モーラ差。木の葉。"}, {"text": "身", "is_correct": false, "explanation": "「み」。ひ→みの一モーラ差。からだ。"}], "explanations": {"日": "「ひ」。一日。", "血": "「ち」。ひ→ちの一モーラ差。体を流れる液。", "気": "「き」。ひ→きの一モーラ差。気持ち。", "葉": "「は」。ひ→はの母音一モーラ差。木の葉。", "身": "「み」。ひ→みの一モーラ差。からだ。"}, "sentence_index": null, "correct_answer": "日"}, "level_3": {"options": [{"text": "日", "is_correct": true, "explanation": "「その日」で特定の一日を表す。"}, {"text": "本", "is_correct": false, "explanation": "意味：本は朝から雨になるものではない。"}, {"text": "店", "is_correct": false, "explanation": "意味：店は時間を表さない。"}, {"text": "駅", "is_correct": false, "explanation": "意味：駅は時間を表さない。"}], "explanations": {"日": "「その日」で特定の一日を表す。", "本": "意味：本は朝から雨になるものではない。", "店": "意味：店は時間を表さない。", "駅": "意味：駅は時間を表さない。"}, "sentence_index": 0, "correct_answer": "日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "次の日を、彼は学校を休んだ。", "explanation": "助詞の混同：時を表す「次の日」に「を」は付けない。"}, {"text": "次の一本の日、彼は学校を休んだ。", "explanation": "助数詞の誤り：日に「本」は使わない。"}, {"text": "彼は学校を休んだ、次の日は明日。", "explanation": "語順と時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ef60f0-cf2f-42ff-bf57-1d01856f6eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
