INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39221, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "日", "is_correct": true, "explanation": "「ひ」。日にち。"}, {"text": "手", "is_correct": false, "explanation": "「て」。ひ→ての一モーラ差。体の一部。"}, {"text": "目", "is_correct": false, "explanation": "「め」。ひ→めの一モーラ差。見る器官。"}, {"text": "毛", "is_correct": false, "explanation": "「け」。ひ→けの一モーラ差。体の毛。"}, {"text": "帆", "is_correct": false, "explanation": "「ほ」。ひ→ほの母音一モーラ差。船の帆。"}], "explanations": {"日": "「ひ」。日にち。", "手": "「て」。ひ→ての一モーラ差。体の一部。", "目": "「め」。ひ→めの一モーラ差。見る器官。", "毛": "「け」。ひ→けの一モーラ差。体の毛。", "帆": "「ほ」。ひ→ほの母音一モーラ差。船の帆。"}, "sentence_index": null, "correct_answer": "日"}, "level_3": {"options": [{"text": "日", "is_correct": true, "explanation": "生まれた一日、つまり誕生日を聞いている。"}, {"text": "紙", "is_correct": false, "explanation": "意味：生まれた紙は意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "意味：生まれた雲は意味が通らない。"}, {"text": "国", "is_correct": false, "explanation": "意味：国は日にちではない。"}], "explanations": {"日": "生まれた一日、つまり誕生日を聞いている。", "紙": "意味：生まれた紙は意味が通らない。", "雲": "意味：生まれた雲は意味が通らない。", "国": "意味：国は日にちではない。"}, "sentence_index": 6, "correct_answer": "日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日をよって気分が変わる。", "explanation": "助詞の混同：「〜によって」の形にする。"}, {"text": "三冊の日によって気分が変わる。", "explanation": "助数詞の誤り：日は「冊」で数えない。"}, {"text": "気分が日によって変わっていた明日。", "explanation": "時制の誤り：「明日」と過去の「ていた」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ef60f0-cf2f-42ff-bf57-1d01856f6eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
