INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39280, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "感", "is_correct": true, "explanation": "「かん」。感じ。"}, {"text": "券", "is_correct": false, "explanation": "「けん」。か→けの一モーラ差。切符やチケット。"}, {"text": "紺", "is_correct": false, "explanation": "「こん」。か→この一モーラ差。濃い青色。"}, {"text": "番", "is_correct": false, "explanation": "「ばん」。か→ばの一モーラ差。順番。"}, {"text": "円", "is_correct": false, "explanation": "「えん」。か→えの一モーラ差。お金の単位。"}], "explanations": {"感": "「かん」。感じ。", "券": "「けん」。か→けの一モーラ差。切符やチケット。", "紺": "「こん」。か→この一モーラ差。濃い青色。", "番": "「ばん」。か→ばの一モーラ差。順番。", "円": "「えん」。か→えの一モーラ差。お金の単位。"}, "sentence_index": null, "correct_answer": "感"}, "level_3": {"options": [{"text": "感", "is_correct": true, "explanation": "「〜た感がある」で「そういう印象がある」を表す。"}, {"text": "窓", "is_correct": false, "explanation": "意味：「遅すぎた窓」は意味が通らない。"}, {"text": "声", "is_correct": false, "explanation": "意味：「遅すぎた声」は意味が通らない。"}, {"text": "店", "is_correct": false, "explanation": "意味：店は印象を表さない。"}], "explanations": {"感": "「〜た感がある」で「そういう印象がある」を表す。", "窓": "意味：「遅すぎた窓」は意味が通らない。", "声": "意味：「遅すぎた声」は意味が通らない。", "店": "意味：店は印象を表さない。"}, "sentence_index": 0, "correct_answer": "感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年は夏が短かった感をする。", "explanation": "助詞の混同：「感がする」と言う。"}, {"text": "今年は夏が短い感がしていた去年。", "explanation": "時制と語順の誤り：「去年」と「今年」が衝突する。"}, {"text": "今年は夏が二つの短かった感がする。", "explanation": "助数詞の誤り：「二つの」は不要で文が壊れる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ef60f0-cf2f-42ff-bf57-1d01856f6eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
