INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41303, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や道具で、何かを強く打つこと。", "primary_collocate": null, "pronunciation": "たたく", "ipa": "tataku", "syllable_count": 3, "sentences": [{"text": "兄は太鼓を強く叩いた。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "あに たいこ つよ たた", "sentence_source": "generated"}, {"text": "ハンマーで釘を叩く。", "target_word": "叩く", "complexity_tier": "T3", "furigana": "くぎ たた", "sentence_source": "generated"}, {"text": "布団を棒で叩いてほこりを出す。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "ふとん ぼう たた だ", "sentence_source": "generated"}, {"text": "怒った客が机を叩いた。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "おこ きゃく つくえ たた", "sentence_source": "generated"}, {"text": "彼はバチで太鼓を叩いている。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "かれ たいこ たた", "sentence_source": "generated"}, {"text": "彼は拳で窓を強く叩いた。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "かれ こぶし まど つよ たた", "sentence_source": "generated"}, {"text": "鉄を何度も叩いて形を作る。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "てつ なんど たた かたち つく", "sentence_source": "generated"}, {"text": "肉を叩くと柔らかくなる。", "target_word": "叩く", "complexity_tier": "T3", "furigana": "にく たた やわ", "sentence_source": "generated"}, {"text": "父は石で殻を叩いて割った。", "target_word": "叩い", "complexity_tier": "T3", "furigana": "ちち いし から たた わ", "sentence_source": "generated"}, {"text": "リズムに合わせてドラムを叩く。", "target_word": "叩く", "complexity_tier": "T3", "furigana": "あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "叩いた", "label": "活用"}, {"form": "叩いて", "label": "活用"}, {"form": "叩かれる", "label": "活用"}, {"form": "叩きながら", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 手や道具で物を強く打つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0472180-effe-4684-a5bf-8f5e9c383b1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41322, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物を料理すること。", "primary_collocate": null, "pronunciation": "ちょうり", "ipa": "tɕoːɾi", "syllable_count": 3, "sentences": [{"text": "調理の時間は三十分です。", "target_word": "調理", "complexity_tier": "T3", "furigana": "ちょうり じかん さんじっぷん", "sentence_source": "generated"}, {"text": "母は魚を上手に調理する。", "target_word": "調理", "complexity_tier": "T3", "furigana": "はは さかな じょうず ちょうり", "sentence_source": "generated"}, {"text": "この野菜は調理が簡単だ。", "target_word": "調理", "complexity_tier": "T3", "furigana": "やさい ちょうり かんたん", "sentence_source": "generated"}, {"text": "調理実習でカレーを作った。", "target_word": "調理", "complexity_tier": "T3", "furigana": "ちょうり じっしゅう つく", "sentence_source": "generated"}, {"text": "肉は十分に調理してから食べよう。", "target_word": "調理", "complexity_tier": "T3", "furigana": "にく じゅうぶん ちょうり た", "sentence_source": "generated"}, {"text": "兄は調理師の学校に通っている。", "target_word": "調理", "complexity_tier": "T3", "furigana": "あに ちょうりし がっこう かよ", "sentence_source": "generated"}, {"text": "調理中は火に気をつけてね。", "target_word": "調理", "complexity_tier": "T3", "furigana": "ちょうりちゅう ひ き", "sentence_source": "generated"}, {"text": "新しい調理器具を買った。", "target_word": "調理", "complexity_tier": "T3", "furigana": "あたら ちょうり きぐ か", "sentence_source": "generated"}, {"text": "この店では客の前で調理する。", "target_word": "調理", "complexity_tier": "T3", "furigana": "みせ きゃく まえ ちょうり", "sentence_source": "generated"}, {"text": "調理された料理が並んでいる。", "target_word": "調理", "complexity_tier": "T3", "furigana": "ちょうり りょうり なら", "sentence_source": "generated"}], "morphological_forms": [{"form": "調理する", "label": "派生"}, {"form": "調理師", "label": "派生"}, {"form": "調理器具", "label": "派生"}, {"form": "調理法", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 食材を加工して料理を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0472180-effe-4684-a5bf-8f5e9c383b1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都会から離れた、いなかの地域。", "primary_collocate": null, "pronunciation": "ちほう", "ipa": "tɕihoː", "syllable_count": 3, "sentences": [{"text": "祖父母は地方に住んでいる。", "target_word": "地方", "complexity_tier": "T3", "furigana": "そふぼ ちほう す", "sentence_source": "generated"}, {"text": "地方の町は静かで好きだ。", "target_word": "地方", "complexity_tier": "T3", "furigana": "ちほう まち しず す", "sentence_source": "generated"}, {"text": "彼は地方から東京に来た。", "target_word": "地方", "complexity_tier": "T3", "furigana": "かれ ちほう とうきょう き", "sentence_source": "generated"}, {"text": "地方では車がないと不便だ。", "target_word": "地方", "complexity_tier": "T3", "furigana": "ちほう くるま ふべん", "sentence_source": "generated"}, {"text": "若い人が地方を出ていく。", "target_word": "地方", "complexity_tier": "T3", "furigana": "わか ひと ちほう で", "sentence_source": "generated"}, {"text": "夏休みに地方へ旅行した。", "target_word": "地方", "complexity_tier": "T3", "furigana": "なつやす ちほう りょこう", "sentence_source": "generated"}, {"text": "地方の野菜は新鮮でおいしい。", "target_word": "地方", "complexity_tier": "T3", "furigana": "ちほう やさい しんせん", "sentence_source": "generated"}, {"text": "都会より地方で暮らしたい。", "target_word": "地方", "complexity_tier": "T3", "furigana": "とかい ちほう く", "sentence_source": "generated"}, {"text": "地方の学校は生徒が少ない。", "target_word": "地方", "complexity_tier": "T3", "furigana": "ちほう がっこう せいと すく", "sentence_source": "generated"}, {"text": "最近、地方に移る家族が増えた。", "target_word": "地方", "complexity_tier": "T3", "furigana": "さいきん ちほう うつ かぞく ふ", "sentence_source": "generated"}], "morphological_forms": [{"form": "地方都市", "label": "派生"}, {"form": "地方出身", "label": "派生"}, {"form": "地方色", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 都会以外のいなかの地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::