INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "就寝", "is_correct": true, "explanation": "しゅうしん。正解。"}, {"text": "就任", "is_correct": false, "explanation": "しゅうにん。三拍目の「し」が「に」に変わる一モーラ差。"}, {"text": "集金", "is_correct": false, "explanation": "しゅうきん。三拍目の「し」が「き」に変わる一モーラ差。"}, {"text": "重心", "is_correct": false, "explanation": "じゅうしん。一拍目の「しゅ」が濁音「じゅ」になる清濁の対立。"}, {"text": "中心", "is_correct": false, "explanation": "ちゅうしん。一拍目の「しゅ」が「ちゅ」に変わる一モーラ差。"}, {"text": "出身", "is_correct": false, "explanation": "しゅっしん。二拍目の長音「う」が促音「っ」に変わる。"}], "explanations": {"就寝": "しゅうしん。正解。", "就任": "しゅうにん。三拍目の「し」が「に」に変わる一モーラ差。", "集金": "しゅうきん。三拍目の「し」が「き」に変わる一モーラ差。", "重心": "じゅうしん。一拍目の「しゅ」が濁音「じゅ」になる清濁の対立。", "中心": "ちゅうしん。一拍目の「しゅ」が「ちゅ」に変わる一モーラ差。", "出身": "しゅっしん。二拍目の長音「う」が促音「っ」に変わる。"}, "sentence_index": null, "correct_answer": "就寝"}, "level_3": {"options": [{"text": "就寝", "is_correct": true, "explanation": "意味：夜に眠りにつくことで、時間を表す文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気に「時間」はなく、夜十時という時刻と結びつかない。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：学校を終えることで、毎晩の時間ではない。"}, {"text": "机", "is_correct": false, "explanation": "意味：物の名前で、「机の時間」という言い方はない。"}], "explanations": {"就寝": "意味：夜に眠りにつくことで、時間を表す文に合う。", "天気": "意味：天気に「時間」はなく、夜十時という時刻と結びつかない。", "卒業": "意味：学校を終えることで、毎晩の時間ではない。", "机": "意味：物の名前で、「机の時間」という言い方はない。"}, "sentence_index": 0, "correct_answer": "就寝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎晩九時を就寝する。", "explanation": "助詞の混同：時刻は「に」で示す。「九時に就寝する」が正しい。"}, {"text": "就寝が昨日は遅くしたので眠い。", "explanation": "語順・係り受けの誤り：主語と述語の関係が崩れている。「昨日は遅く就寝したので眠い」が正しい。"}, {"text": "明日の夜は十時に就寝した。", "explanation": "活用・アスペクトの誤り：未来の「明日」に過去の「た」は合わない。「就寝する」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎晩九時で就寝する。", "corrected_sentence": "祖父は毎晩九時に就寝する。", "error_description": "助詞の混同：時刻を表すには「で」ではなく「に」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時刻を表す格助詞で、「九時に就寝する」となる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、時刻には使えない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表し、時刻の後では不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、時刻には使えない。"}], "correct_answer": "に", "explanations": {"に": "時刻を表す格助詞で、「九時に就寝する」となる。", "を": "目的語を表す助詞で、時刻には使えない。", "で": "場所や手段を表し、時刻の後では不自然。", "へ": "方向を表し、時刻には使えない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起床", "is_correct": true, "explanation": "寝床から起きることで、就寝の反対。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ること自体で、就寝に近く反対ではない。"}, {"text": "休憩", "is_correct": false, "explanation": "少し休むことで、反対の関係ではない。"}, {"text": "帰宅", "is_correct": false, "explanation": "家に帰ることで、寝ることとは反対の関係にない。"}], "correct_answer": "起床", "explanations": {"起床": "寝床から起きることで、就寝の反対。", "睡眠": "眠ること自体で、就寝に近く反対ではない。", "休憩": "少し休むことで、反対の関係ではない。", "帰宅": "家に帰ることで、寝ることとは反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "就寝", "is_correct": true, "explanation": "しゅうしん。正解。"}, {"text": "昇進", "is_correct": false, "explanation": "しょうしん。一拍目の「しゅ」が「しょ」に変わる一モーラ差。"}, {"text": "囚人", "is_correct": false, "explanation": "しゅうじん。三拍目の「し」が濁音「じ」になる清濁の対立。"}, {"text": "中心", "is_correct": false, "explanation": "ちゅうしん。一拍目「しゅ」が「ちゅ」になる一モーラ差。"}, {"text": "集金", "is_correct": false, "explanation": "しゅうきん。三拍目「し」が「き」になる一モーラ差。"}], "explanations": {"就寝": "しゅうしん。正解。", "昇進": "しょうしん。一拍目の「しゅ」が「しょ」に変わる一モーラ差。", "囚人": "しゅうじん。三拍目の「し」が濁音「じ」になる清濁の対立。", "中心": "ちゅうしん。一拍目「しゅ」が「ちゅ」になる一モーラ差。", "集金": "しゅうきん。三拍目「し」が「き」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "就寝"}, "level_3": {"options": [{"text": "就寝", "is_correct": true, "explanation": "意味：眠っている間に地震が起きたという自然な文。"}, {"text": "入学", "is_correct": false, "explanation": "意味：学校に入ることで、「入学中」とは言わない。"}, {"text": "誕生", "is_correct": false, "explanation": "連語：「誕生中」という言い方はない。"}, {"text": "到着", "is_correct": false, "explanation": "意味：着く瞬間の動作で、「到着中」は不自然。"}], "explanations": {"就寝": "意味：眠っている間に地震が起きたという自然な文。", "入学": "意味：学校に入ることで、「入学中」とは言わない。", "誕生": "連語：「誕生中」という言い方はない。", "到着": "意味：着く瞬間の動作で、「到着中」は不自然。"}, "sentence_index": 6, "correct_answer": "就寝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早めの就寝が心がけている。", "explanation": "助詞の混同：心がける対象は「を」で示す。「就寝を心がけている」が正しい。"}, {"text": "昨日は早めの就寝を心がけるだろう。", "explanation": "活用・アスペクトの誤り：過去の「昨日」と推量の「だろう」が合わない。"}, {"text": "早めの就寝に心がけている。", "explanation": "助詞の混同：「心がける」の対象は「に」ではなく「を」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病院の就寝を夜九時だ。", "corrected_sentence": "病院の就寝は夜九時だ。", "error_description": "助詞の混同：「〜は…だ」の主題を示すには「を」ではなく「は」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41286, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、「就寝は夜九時だ」と説明する文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「だ」で終わる文には合わない。"}, {"text": "に", "is_correct": false, "explanation": "着点・時を表し、この位置では非文。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、「就寝で夜九時だ」は不自然。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、「就寝は夜九時だ」と説明する文になる。", "を": "目的語を示す助詞で、「だ」で終わる文には合わない。", "に": "着点・時を表し、この位置では非文。", "で": "場所・手段を表し、「就寝で夜九時だ」は不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起床", "is_correct": true, "explanation": "朝起きることで、就寝と対になる。"}, {"text": "昼寝", "is_correct": false, "explanation": "昼に寝ることで、寝る点では同じ。"}, {"text": "入浴", "is_correct": false, "explanation": "お風呂に入ることで、反対ではない。"}, {"text": "夕食", "is_correct": false, "explanation": "夜の食事で、反対の関係ではない。"}], "correct_answer": "起床", "explanations": {"起床": "朝起きることで、就寝と対になる。", "昼寝": "昼に寝ることで、寝る点では同じ。", "入浴": "お風呂に入ることで、反対ではない。", "夕食": "夜の食事で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41287, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "就寝", "is_correct": true, "explanation": "正解。"}, {"text": "中心", "is_correct": false, "explanation": "ちゅうしん。一拍目「しゅ」が「ちゅ」に変わる一モーラ差。"}, {"text": "出身", "is_correct": false, "explanation": "しゅっしん。二拍目の長音「う」が促音「っ」に変わる。"}, {"text": "就任", "is_correct": false, "explanation": "しゅうにん。三拍目「し」が「に」に変わる一モーラ差。"}, {"text": "重心", "is_correct": false, "explanation": "じゅうしん。一拍目が濁音「じゅ」になる清濁の対立。"}], "explanations": {"就寝": "正解。", "中心": "ちゅうしん。一拍目「しゅ」が「ちゅ」に変わる一モーラ差。", "出身": "しゅっしん。二拍目の長音「う」が促音「っ」に変わる。", "就任": "しゅうにん。三拍目「し」が「に」に変わる一モーラ差。", "重心": "じゅうしん。一拍目が濁音「じゅ」になる清濁の対立。"}, "sentence_index": null, "correct_answer": "就寝"}, "level_3": {"options": [{"text": "就寝", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "意味：物の名前で「寝具した」とは言わない。"}, {"text": "寝室", "is_correct": false, "explanation": "意味：部屋の名前で、動作を表さない。"}, {"text": "深夜", "is_correct": false, "explanation": "項構造：時を表す名詞で「する」が付かない。"}], "explanations": {"就寝": "正解：文脈に合う。", "寝具": "意味：物の名前で「寝具した」とは言わない。", "寝室": "意味：部屋の名前で、動作を表さない。", "深夜": "項構造：時を表す名詞で「する」が付かない。"}, "sentence_index": 0, "correct_answer": "就寝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母はもう就寝を食べている。", "explanation": "助詞・項構造の誤り：就寝は「食べる」対象ではない。「就寝している」が正しい。"}, {"text": "母は明日もう就寝した。", "explanation": "活用・アスペクトの誤り：「明日」と過去の「た」が合わない。"}, {"text": "就寝している母はもう、は。", "explanation": "語順の誤り：主題の「は」が文末にあり文が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
