INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41303, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叩く", "is_correct": true, "explanation": "正解。"}, {"text": "痛く", "is_correct": false, "explanation": "いたく。一拍目「た」が「い」に変わる一モーラ差。"}, {"text": "炊く", "is_correct": false, "explanation": "たく。二拍目「た」が脱落する。"}, {"text": "畳", "is_correct": false, "explanation": "たたみ。三拍目「く」が「み」に変わる一モーラ差。"}], "explanations": {"叩く": "正解。", "痛く": "いたく。一拍目「た」が「い」に変わる一モーラ差。", "炊く": "たく。二拍目「た」が脱落する。", "畳": "たたみ。三拍目「く」が「み」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "叩く"}, "level_3": {"options": [{"text": "叩い", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "読ん", "is_correct": false, "explanation": "意味：鉄を読んでも形はできない。"}, {"text": "泳い", "is_correct": false, "explanation": "項構造：「泳ぐ」は対象の「を」を取らない。"}, {"text": "拭い", "is_correct": false, "explanation": "意味：拭いても鉄の形は変わらない。"}], "explanations": {"叩い": "正解：文脈に合う。", "読ん": "意味：鉄を読んでも形はできない。", "泳い": "項構造：「泳ぐ」は対象の「を」を取らない。", "拭い": "意味：拭いても鉄の形は変わらない。"}, "sentence_index": 6, "correct_answer": "叩い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "リズムに合わせてドラムが叩く。", "explanation": "助詞の混同：叩く対象は「を」で示す。"}, {"text": "リズムに合わせて大口を叩く。", "explanation": "別の義項：「大口を叩く」は物を打つ意味ではない。"}, {"text": "ドラムを叩くリズムに合わせて昨日だ。", "explanation": "語順の誤り：時の語が文末にあり文が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b462c27e-a59c-4825-81ad-8b0cf49f1449') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
