INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "とても暑い夏の日や天気のこと。", "primary_collocate": null, "pronunciation": "えんてん", "ipa": "eɴteɴ", "syllable_count": 4, "sentences": [{"text": "炎天の日は外に出たくない。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "今日は朝から炎天だった。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天の中、みんなで走った。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天が一週間も続いている。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天の道を歩いて帰った。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "八月の炎天はとてもつらい。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天でも弟は元気に遊んだ。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天に帽子を忘れてしまった。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "炎天を避けて朝に練習する。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}, {"text": "この夏は炎天ばかりだった。", "target_word": "炎天", "complexity_tier": "T3", "furigana": "えんてん", "sentence_source": "generated"}], "morphological_forms": [{"form": "炎天下", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 夏のとても暑い天気や日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc87efa-2c0f-4e81-9faf-1c6ef115f7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET con