INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42821, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "卵を産み、肉も食べられる、よく飼われる鳥。", "primary_collocate": null, "pronunciation": "にわとり", "ipa": "ɲiwatoɾi", "syllable_count": 4, "sentences": [{"text": "鶏が朝早く鳴いている。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "祖母の家で鶏を飼っている。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "鶏の卵を毎朝集める。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "庭で三羽の鶏が歩いている。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "鶏は空を高く飛べない。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "鶏にえさをあげるのが好きだ。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "この鶏は毎日卵を産む。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "鶏の声で目が覚めた。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "小屋から鶏が逃げてしまった。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}, {"text": "白い鶏と茶色い鶏がいる。", "target_word": "鶏", "complexity_tier": "T3", "furigana": "にわとり", "sentence_source": "generated"}], "morphological_forms": [{"form": "羽", "label": "助数詞"}, {"form": "鶏小屋", "label": "派生"}, {"form": "鶏肉", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 卵を産む家で飼われる鳥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc87efa-2c0f-4e81-9faf-1c6ef115f7e7') ON