INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42776, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "相手や物事と正面から向かい合うこと。", "primary_collocate": null, "pronunciation": "むきあう", "ipa": "mɯkiaɯ", "syllable_count": 4, "sentences": [{"text": "自分の弱さと向き合う。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "二人は机をはさんで向き合った。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "問題としっかり向き合いたい。", "target_word": "向き合い", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "友だちと向き合って話した。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "失敗と向き合うのは難しい。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "彼は自分の気持ちに向き合っている。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "向き合って座ると少し照れる。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "病気と向き合いながら生きる。", "target_word": "向き合い", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "親と向き合う時間を作った。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}, {"text": "将来と向き合う勇気がほしい。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "むきあう", "sentence_source": "generated"}], "morphological_forms": [{"form": "向き合った", "label": "活用"}, {"form": "向き合って", "label": "活用"}, {"form": "向き合わない", "label": "活用"}, {"form": "向き合える", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 正面から向かい合って対する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'cl