INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すみからすみまで、のこらずしっかりすること。", "primary_collocate": null, "pronunciation": "てってい", "ipa": "tetteː", "syllable_count": 4, "sentences": [{"text": "掃除を徹底してやった。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "手洗いの徹底をお願いします。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "彼は何でも徹底する人だ。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "安全の確認を徹底しよう。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "徹底した練習で上手になった。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "ルールの徹底が大切だ。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "先生は時間を守ることを徹底した。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "ごみの分別を徹底している。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "徹底して調べたら原因がわかった。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "準備の徹底で試合に勝った。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}], "morphological_forms": [{"form": "徹底する", "label": "派生"}, {"form": "徹底的", "label": "派生"}, {"form": "徹底した", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 残らずしっかりやりとおすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc87efa-2c