INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42800, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をのこさず、すみずみまで行き渡らせること。", "primary_collocate": null, "pronunciation": "てってい", "ipa": "tetteː", "syllable_count": 4, "sentences": [{"text": "連絡の徹底が足りなかった。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "店ではマスクの着用を徹底した。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "徹底した管理で事故が減った。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "会社は情報の管理を徹底する。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "注意が徹底されていなかった。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "全員に規則を徹底させる。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "徹底した調査が行われた。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "節電の徹底をみんなで決めた。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "学校で挨拶を徹底している。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}, {"text": "その方針は社員に徹底された。", "target_word": "徹底", "complexity_tier": "T3", "furigana": "てってい", "sentence_source": "generated"}], "morphological_forms": [{"form": "徹底する", "label": "派生"}, {"form": "徹底的", "label": "派生"}, {"form": "徹底させる", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 方針などを全体に行き渡らせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc87efa-2c0f-4e81-9faf-1c6ef115f7e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42670, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炎天", "is_correct": true, "explanation": "正解：えんてん。"}, {"text": "観点", "is_correct": false, "explanation": "かんてん：最初の「え」が「か」に変わる一モーラ差。"}, {"text": "栄転", "is_correct": false, "explanation": "えいてん：二拍目「ん」が「い」に変わる一モーラ差。"}, {"text": "沿線", "is_correct": false, "explanation": "えんせん：三拍目「て」が「せ」に変わる一モーラ差。"}, {"text": "転々", "is_correct": false, "explanation": "てんてん：最初の「え」が「て」に変わる一モーラ差。"}], "explanations": {"炎天": "正解：えんてん。", "観点": "かんてん：最初の「え」が「か」に変わる一モーラ差。", "栄転": "えいてん：二拍目「ん」が「い」に変わる一モーラ差。", "沿線": "えんせん：三拍目「て」が「せ」に変わる一モーラ差。", "転々": "てんてん：最初の「え」が「て」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "炎天"}, "level_3": {"options": [{"text": "炎天", "is_correct": true, "explanation": "とても暑い日を表し、外に出たくない理由になる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：文房具であり「日」を修飾しない。"}, {"text": "椅子", "is_correct": false, "explanation": "意味：家具であり、「椅子の日」とは言わない。"}, {"text": "夜中", "is_correct": false, "explanation": "連語：「夜中の日」とは言わない。"}], "explanations": {"炎天": "とても暑い日を表し、外に出たくない理由になる。", "鉛筆": "意味：文房具であり「日」を修飾しない。", "椅子": "意味：家具であり、「椅子の日」とは言わない。", "夜中": "連語：「夜中の日」とは言わない。"}, "sentence_index": 0, "correct_answer": "炎天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一枚の炎天が続いている。", "explanation": "助数詞の誤り：天気に「枚」は使えない。"}, {"text": "炎天を一週間も続いている。", "explanation": "助詞の混同：自動詞「続く」の主語は「が」で示す。"}, {"text": "炎天が一週間も続いた明日。", "explanation": "活用・アスペクトの誤り：過去形と「明日」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae9a665-6756-4706-a9e4-537329f1afe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "炎天を外を歩いた。", "corrected_sentence": "炎天の中、外を歩いた。", "error_description": "助詞の誤り：「炎天を外を」と「を」が重なる。「炎天の中」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae9a665-6756-4706-a9e4-537329f1afe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42670, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "起点を表し「朝から」で始まりの時点を示す。"}, {"text": "で", "is_correct": false, "explanation": "「朝で炎天だった」は非文。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、「朝を炎天だった」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、時間には使えない。"}], "correct_answer": "から", "explanations": {"から": "起点を表し「朝から」で始まりの時点を示す。", "で": "「朝で炎天だった」は非文。", "を": "目的語標示で、「朝を炎天だった」は非文。", "へ": "方向を表し、時間には使えない。"}, "error_tags": {"で": "instrument", "を": "object_marking", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厳寒", "is_correct": true, "explanation": "きびしい寒さで、夏の厳しい暑さの対義。"}, {"text": "猛暑", "is_correct": false, "explanation": "類義語で、対義ではない。"}, {"text": "晴天", "is_correct": false, "explanation": "晴れた空で、暑さの反対ではない。"}, {"text": "真夏", "is_correct": false, "explanation": "時期を表し、対義ではない。"}], "correct_answer": "厳寒", "explanations": {"厳寒": "きびしい寒さで、夏の厳しい暑さの対義。", "猛暑": "類義語で、対義ではない。", "晴天": "晴れた空で、暑さの反対ではない。", "真夏": "時期を表し、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae9a665-6756-4706-a9e4-537329f1afe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42670, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炎天", "is_correct": true, "explanation": "正解：えんてん。"}, {"text": "寒天", "is_correct": false, "explanation": "かんてん：「え」→「か」の一モーラ差。"}, {"text": "先天", "is_correct": false, "explanation": "せんてん：「え」→「せ」の一モーラ差。"}, {"text": "点々", "is_correct": false, "explanation": "てんてん：「え」→「て」の一モーラ差。"}, {"text": "栄転", "is_correct": false, "explanation": "えいてん：「ん」→「い」の一モーラ差。"}, {"text": "沿線", "is_correct": false, "explanation": "えんせん：「て」→「せ」の一モーラ差。"}], "explanations": {"炎天": "正解：えんてん。", "寒天": "かんてん：「え」→「か」の一モーラ差。", "先天": "せんてん：「え」→「せ」の一モーラ差。", "点々": "てんてん：「え」→「て」の一モーラ差。", "栄転": "えいてん：「ん」→「い」の一モーラ差。", "沿線": "えんせん：「て」→「せ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "炎天"}, "level_3": {"options": [{"text": "炎天", "is_correct": true, "explanation": "厳しい暑さの日でも弟が元気だったことを表す。"}, {"text": "机", "is_correct": false, "explanation": "意味：物であり天気を表さない。"}, {"text": "急いで", "is_correct": false, "explanation": "項構造：副詞的な形で「でも」に続かない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "意味：文房具で、「消しゴムでも弟は遊んだ」は条件にならない。"}], "explanations": {"炎天": "厳しい暑さの日でも弟が元気だったことを表す。", "机": "意味：物であり天気を表さない。", "急いで": "項構造：副詞的な形で「でも」に続かない。", "消しゴム": "意味：文房具で、「消しゴムでも弟は遊んだ」は条件にならない。"}, "sentence_index": 6, "correct_answer": "炎天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この夏は炎天ばかりだっている。", "explanation": "活用の誤り：「だった」に「いる」は付かない。"}, {"text": "この夏が炎天をばかりだった。", "explanation": "助詞の混同：「を」は不要で、主題は「は」がよい。"}, {"text": "ばかりこの夏は炎天だった。", "explanation": "語順の誤り：「ばかり」は名詞の後に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae9a665-6756-4706-a9e4-537329f1afe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_error