INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42800, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "徹底", "is_correct": true, "explanation": "正解：てってい。"}, {"text": "撤退", "is_correct": false, "explanation": "てったい：「て」→「た」の一モーラ差。"}, {"text": "鉄製", "is_correct": false, "explanation": "てっせい：「て」→「せ」の一モーラ差。"}, {"text": "設定", "is_correct": false, "explanation": "せってい：「て」→「せ」の一モーラ差。"}], "explanations": {"徹底": "正解：てってい。", "撤退": "てったい：「て」→「た」の一モーラ差。", "鉄製": "てっせい：「て」→「せ」の一モーラ差。", "設定": "せってい：「て」→「せ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "徹底"}, "level_3": {"options": [{"text": "徹底", "is_correct": true, "explanation": "すみずみまで行き届いた調査を表す。"}, {"text": "満腹", "is_correct": false, "explanation": "意味：調査が満腹にはならない。"}, {"text": "帰宅", "is_correct": false, "explanation": "連語：「帰宅した調査」とは言わない。"}, {"text": "誕生", "is_correct": false, "explanation": "意味：調査が誕生したは不自然。"}], "explanations": {"徹底": "すみずみまで行き届いた調査を表す。", "満腹": "意味：調査が満腹にはならない。", "帰宅": "連語：「帰宅した調査」とは言わない。", "誕生": "意味：調査が誕生したは不自然。"}, "sentence_index": 6, "correct_answer": "徹底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その方針は社員を徹底された。", "explanation": "助詞の混同：受身で行き渡る相手は「に」で示す。"}, {"text": "その方針は社員に徹底されるた。", "explanation": "活用の誤り：「された」が正しい。"}, {"text": "社員にその徹底方針はされた。", "explanation": "語順の誤り：文が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ae9a665-6756-4706-a9e4-537329f1afe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
