INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42852, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "ほんの少しだけ、という意味です。", "primary_collocate": null, "pronunciation": "わずか", "ipa": "wa͍zɯka", "syllable_count": 3, "sentences": [{"text": "財布にお金が僅か残っている。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか さいふ かね のこ", "sentence_source": "generated"}, {"text": "僅か五分で宿題が終わった。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか ごふん しゅくだい お", "sentence_source": "generated"}, {"text": "試合は僅か一点差で負けた。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか しあい いってんさ ま", "sentence_source": "generated"}, {"text": "僅か三人しか来なかった。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか さんにん き", "sentence_source": "generated"}, {"text": "駅まで僅か百メートルだ。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか えき ひゃく", "sentence_source": "generated"}, {"text": "彼は僅か十歳で大学に入った。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか かれ じゅっさい だいがく はい", "sentence_source": "generated"}, {"text": "僅かな時間でも練習している。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか じかん れんしゅう", "sentence_source": "generated"}, {"text": "水が僅かに残っている。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか みず のこ", "sentence_source": "generated"}, {"text": "夏休みも残り僅かだ。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか なつやす のこ", "sentence_source": "generated"}, {"text": "僅かな違いに気づいた。", "target_word": "僅か", "complexity_tier": "T3", "furigana": "わずか ちが き", "sentence_source": "generated"}], "morphological_forms": [{"form": "僅かな", "label": "活用"}, {"form": "僅かに", "label": "活用"}, {"form": "僅かだ", "label": "活用"}], "register": "formal", "sense_fingerprint": "副詞 | 数や量がほんの少しであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}':