INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43003, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体を作る主な栄養素の一つで、アミノ酸からできています。肉や魚、卵、豆に多く含まれます。", "primary_collocate": null, "pronunciation": "たんぱく", "ipa": "tampakɯ", "syllable_count": 4, "sentences": [{"text": "蛋白はアミノ酸からできている。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく さん", "sentence_source": "generated"}, {"text": "大豆は蛋白を多く含む。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく だいず おお ふく", "sentence_source": "generated"}, {"text": "蛋白を毎日しっかりとろう。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく まいにち", "sentence_source": "generated"}, {"text": "この肉は蛋白が豊富だ。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく にく ほうふ", "sentence_source": "generated"}, {"text": "選手は蛋白を多めに食べる。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく せんしゅ おお た", "sentence_source": "generated"}, {"text": "蛋白が不足すると体が弱る。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく ふそく からだ よわ", "sentence_source": "generated"}, {"text": "ヨーグルトで蛋白を補う。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく おぎな", "sentence_source": "generated"}, {"text": "動物の蛋白と植物の蛋白がある。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく どうぶつ しょくぶつ", "sentence_source": "generated"}, {"text": "食事の蛋白の量を調べた。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく しょくじ りょう しら", "sentence_source": "generated"}, {"text": "卵の白身は蛋白でできている。", "target_word": "蛋白", "complexity_tier": "T3", "furigana": "たんぱく たまご しろみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "蛋白質", "label": "派生"}, {"form": "植物性蛋白", "label": "派生"}, {"form": "動物性蛋白", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | アミノ酸からなる主要な栄養素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107551a-6bec-45fb-90d8-f967b61d2aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
