INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山や森にすむ、体の大きい動物。", "primary_collocate": null, "pronunciation": "くま", "ipa": "kɯma", "syllable_count": 2, "sentences": [{"text": "山で熊を見た。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま やま み", "sentence_source": "generated"}, {"text": "熊は冬に眠る。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま ふゆ ねむ", "sentence_source": "generated"}, {"text": "森に熊がいるらしい。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま もり", "sentence_source": "generated"}, {"text": "熊が川で魚をとっている。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま かわ さかな", "sentence_source": "generated"}, {"text": "動物園で熊の子どもを見た。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま どうぶつえん こ み", "sentence_source": "generated"}, {"text": "熊は蜂蜜が好きだ。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま はちみつ す", "sentence_source": "generated"}, {"text": "熊に会ったら静かに逃げよう。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま あ しず に", "sentence_source": "generated"}, {"text": "あの熊はとても大きい。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま おお", "sentence_source": "generated"}, {"text": "熊の足あとが雪に残っていた。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま あし ゆき のこ", "sentence_source": "generated"}, {"text": "村の近くに熊が出た。", "target_word": "熊", "complexity_tier": "T3", "furigana": "くま むら ちか で", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 森にすむ大きな動物のくま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107551a-6bec-45fb-90d8-f967b61d2aef') ON CONFLICT (sense_id, asset_type) DO UPDA