INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51441, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うまは、どうぶつのなまえです。のれるどうぶつです。", "primary_collocate": null, "pronunciation": "うま", "ipa": "ɯma", "syllable_count": 2, "sentences": [{"text": "牧場で馬に乗った。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま ぼくじょう の", "sentence_source": "generated"}, {"text": "馬は速く走る。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま はや はし", "sentence_source": "generated"}, {"text": "白い馬が草を食べている。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま しろ くさ た", "sentence_source": "generated"}, {"text": "祖父は馬を育てている。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま そふ そだ", "sentence_source": "generated"}, {"text": "馬の背中はとても高い。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま せなか たか", "sentence_source": "generated"}, {"text": "昔の人は馬で旅をした。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま むかし ひと たび", "sentence_source": "generated"}, {"text": "この馬は人になれている。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま ひと", "sentence_source": "generated"}, {"text": "子どもたちが馬を見に来た。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま こ み き", "sentence_source": "generated"}, {"text": "馬がゆっくり歩いている。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま ある", "sentence_source": "generated"}, {"text": "競馬場で馬が走るのを見た。", "target_word": "馬", "complexity_tier": "T3", "furigana": "うま けいばじょう はし み", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 人が乗る大きな動物のうま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5107551a-6bec-45fb-90d8-f967b61d2aef') ON CONFLICT (sense_id, ass