INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42852, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "僅か", "is_correct": true, "explanation": "正解。わずか。"}, {"text": "静か", "is_correct": false, "explanation": "しずか。最初のモーラ「わ」が「し」に変わる一モーラ差。"}, {"text": "輪っか", "is_correct": false, "explanation": "わっか。二番目のモーラ「ず」が促音「っ」に変わる。"}, {"text": "和歌", "is_correct": false, "explanation": "わか。モーラ「ず」がなく、一モーラ短い。"}], "explanations": {"僅か": "正解。わずか。", "静か": "しずか。最初のモーラ「わ」が「し」に変わる一モーラ差。", "輪っか": "わっか。二番目のモーラ「ず」が促音「っ」に変わる。", "和歌": "わか。モーラ「ず」がなく、一モーラ短い。"}, "sentence_index": null, "correct_answer": "僅か"}, "level_3": {"options": [{"text": "僅か", "is_correct": true, "explanation": "ほんの少しお金が残っている、という意味で自然。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」は否定と結びつくので、肯定文には入らない。"}, {"text": "急に", "is_correct": false, "explanation": "アスペクト：「急に」は変化を表し、「残っている」状態とは合わない。"}, {"text": "一緒に", "is_correct": false, "explanation": "意味：お金が誰かと一緒に残るという意味になり、不自然。"}], "explanations": {"僅か": "ほんの少しお金が残っている、という意味で自然。", "決して": "連語：「決して」は否定と結びつくので、肯定文には入らない。", "急に": "アスペクト：「急に」は変化を表し、「残っている」状態とは合わない。", "一緒に": "意味：お金が誰かと一緒に残るという意味になり、不自然。"}, "sentence_index": 0, "correct_answer": "僅か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "僅か三人がたくさん来た。", "explanation": "意味の誤り：「僅か」は少なさを強調するので「たくさん」と矛盾する。"}, {"text": "僅か千人もの人が来た。", "explanation": "意味の誤り：「僅か」は少なさを、「もの」は多さを強調するので矛盾する。"}, {"text": "三人しか来なかった僅か。", "explanation": "語順の誤り：副詞「僅か」は数の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDE