INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42852, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "たくさん", "is_correct": true, "explanation": "量が多いことを表し、「僅か」の反対。"}, {"text": "少し", "is_correct": false, "explanation": "量が少ないことを表す類義語で、反対ではない。"}, {"text": "やや", "is_correct": false, "explanation": "程度が少し、という意味で反対ではない。"}, {"text": "ちょうど", "is_correct": false, "explanation": "数や量がぴったりという意味で、多い少ないの反対関係はない。"}], "correct_answer": "たくさん", "explanations": {"たくさん": "量が多いことを表し、「僅か」の反対。", "少し": "量が少ないことを表す類義語で、反対ではない。", "やや": "程度が少し、という意味で反対ではない。", "ちょうど": "数や量がぴったりという意味で、多い少ないの反対関係はない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42852, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "僅か", "is_correct": true, "explanation": "正解。読みはわずか。"}, {"text": "鈴鹿", "is_correct": false, "explanation": "すずか。頭の「わ」が「す」。"}, {"text": "若葉", "is_correct": false, "explanation": "わかば。「ずか」が「かば」。"}, {"text": "渡し", "is_correct": false, "explanation": "わたし。「ずか」が「たし」。"}], "explanations": {"僅か": "正解。読みはわずか。", "鈴鹿": "すずか。頭の「わ」が「す」。", "若葉": "わかば。「ずか」が「かば」。", "渡し": "わたし。「ずか」が「たし」。"}, "sentence_index": null, "correct_answer": "僅か"}, "level_3": {"options": [{"text": "僅か", "is_correct": true, "explanation": "少しの時間でも、という意味で自然。"}, {"text": "真っ赤", "is_correct": false, "explanation": "意味：時間に色はないので、「真っ赤な時間」はおかしい。"}, {"text": "丈夫", "is_correct": false, "explanation": "意味：「丈夫」は物や体の強さを表し、時間には使わない。"}, {"text": "有名", "is_correct": false, "explanation": "連語：時間が有名だという結びつきは不自然。"}], "explanations": {"僅か": "少しの時間でも、という意味で自然。", "真っ赤": "意味：時間に色はないので、「真っ赤な時間」はおかしい。", "丈夫": "意味：「丈夫」は物や体の強さを表し、時間には使わない。", "有名": "連語：時間が有名だという結びつきは不自然。"}, "sentence_index": 6, "correct_answer": "僅か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "僅かな違いがとても大きい。", "explanation": "意味の誤り：「僅か」は小さいことを表すので「とても大きい」と矛盾する。"}, {"text": "違いに僅かな気づいた。", "explanation": "語順の誤り：「僅かな」は名詞「違い」の前に置く。"}, {"text": "僅かな違いを気づいた。", "explanation": "助詞の誤り：「気づく」は「を」ではなく「に」をとる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
