INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43002, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛋白", "is_correct": true, "explanation": "正解。たんぱく。"}, {"text": "関白", "is_correct": false, "explanation": "かんぱく。最初の「た」が「か」に変わる一モーラ差。"}, {"text": "短パン", "is_correct": false, "explanation": "たんぱん。最後の「く」が「ん」に変わる一モーラ差。"}, {"text": "短髪", "is_correct": false, "explanation": "たんぱつ。最後の「く」が「つ」に変わる一モーラ差。"}, {"text": "短波", "is_correct": false, "explanation": "たんぱ。最後の「く」がなく一モーラ短い。"}], "explanations": {"蛋白": "正解。たんぱく。", "関白": "かんぱく。最初の「た」が「か」に変わる一モーラ差。", "短パン": "たんぱん。最後の「く」が「ん」に変わる一モーラ差。", "短髪": "たんぱつ。最後の「く」が「つ」に変わる一モーラ差。", "短波": "たんぱ。最後の「く」がなく一モーラ短い。"}, "sentence_index": null, "correct_answer": "蛋白"}, "level_3": {"options": [{"text": "蛋白", "is_correct": true, "explanation": "卵は蛋白の多い食べ物なので自然。"}, {"text": "骨", "is_correct": false, "explanation": "意味：卵の中に骨はない。"}, {"text": "砂糖", "is_correct": false, "explanation": "意味：卵に砂糖は多く含まれていない。"}, {"text": "種", "is_correct": false, "explanation": "意味：種は植物のもので、卵にはない。"}], "explanations": {"蛋白": "卵は蛋白の多い食べ物なので自然。", "骨": "意味：卵の中に骨はない。", "砂糖": "意味：卵に砂糖は多く含まれていない。", "種": "意味：種は植物のもので、卵にはない。"}, "sentence_index": 0, "correct_answer": "蛋白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "運動の後は蛋白を大切だ。", "explanation": "助詞の誤り：「大切だ」の主語は「を」ではなく「が」で表す。"}, {"text": "運動の後は一枚の蛋白が大切だ。", "explanation": "助数詞の誤り：栄養素の蛋白は「枚」で数えない。"}, {"text": "運動の後は蛋白に着替える。", "explanation": "意味の誤り：蛋白は栄養素で、服のように着替えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43002, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卵には蛋白を多い。", "corrected_sentence": "卵には蛋白が多い。", "error_description": "助詞の誤り：「多い」の主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43002, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「作る」の目的語「筋肉」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点を表し、「作る」の目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、この文では非文。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「作る」の目的語「筋肉」を示す。", "に": "「に」は着点を表し、「作る」の目的語にならない。", "へ": "「へ」は方向を表し、この文では非文。", "より": "「より」は比較を表し、ここでは意味が通らない。"}, "error_tags": {"に": "location_vs_target", "へ": "direction", "より": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43002, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛋白", "is_correct": true, "explanation": "正解。読みはたんぱく。"}, {"text": "短冊", "is_correct": false, "explanation": "たんざく。三番目の「ぱ」が「ざ」。"}, {"text": "散髪", "is_correct": false, "explanation": "さんぱつ。頭と終わりのモーラが違う。"}, {"text": "単語", "is_correct": false, "explanation": "たんご。「ぱく」が「ご」。"}], "explanations": {"蛋白": "正解。読みはたんぱく。", "短冊": "たんざく。三番目の「ぱ」が「ざ」。", "散髪": "さんぱつ。頭と終わりのモーラが違う。", "単語": "たんご。「ぱく」が「ご」。"}, "sentence_index": null, "correct_answer": "蛋白"}, "level_3": {"options": [{"text": "蛋白", "is_correct": true, "explanation": "魚は蛋白を多く含む食べ物なので自然。"}, {"text": "砂糖", "is_correct": false, "explanation": "意味：魚に砂糖は多く含まれていない。"}, {"text": "種", "is_correct": false, "explanation": "意味：種は植物のもので、魚にはない。"}, {"text": "紙", "is_correct": false, "explanation": "意味：魚に紙は含まれていない。"}], "explanations": {"蛋白": "魚は蛋白を多く含む食べ物なので自然。", "砂糖": "意味：魚に砂糖は多く含まれていない。", "種": "意味：種は植物のもので、魚にはない。", "紙": "意味：魚に紙は含まれていない。"}, "sentence_index": 6, "correct_answer": "蛋白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "植物の蛋白を体にいい。", "explanation": "助詞の誤り：「いい」の主語は「を」ではなく「も／が」で表す。"}, {"text": "植物の三匹の蛋白も体にいい。", "explanation": "助数詞の誤り：栄養素を「匹」で数えることはない。"}, {"text": "植物の蛋白で体を洗う。", "explanation": "意味の誤り：蛋白は栄養素で、体を洗うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
