INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43002, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾節の主語を示す「の」で、「蛋白の多い料理」は自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、「多い」の前では非文。"}, {"text": "に", "is_correct": false, "explanation": "「に」では蛋白が多い主体にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、この位置では非文。"}], "correct_answer": "の", "explanations": {"の": "連体修飾節の主語を示す「の」で、「蛋白の多い料理」は自然。", "を": "「を」は目的語を示し、「多い」の前では非文。", "に": "「に」では蛋白が多い主体にならず不自然。", "へ": "「へ」は方向を表し、この位置では非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
