INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (43003, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在を表す「ある」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は自動詞なので「を」はとれない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「ある」と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "存在を表す「ある」の主語を示す。", "を": "「ある」は自動詞なので「を」はとれない。", "へ": "「へ」は方向を表し、「ある」と合わない。", "より": "「より」は比較を表し、ここでは文が成立しない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "より": "other"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51417, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。あおい。"}, {"text": "赤い", "is_correct": false, "explanation": "あかい。二番目の「お」が「か」に変わる一モーラ差。"}, {"text": "甘い", "is_correct": false, "explanation": "あまい。二番目の「お」が「ま」に変わる一モーラ差。"}, {"text": "荒い", "is_correct": false, "explanation": "あらい。二番目の「お」が「ら」に変わる一モーラ差。"}, {"text": "暑い", "is_correct": false, "explanation": "あつい。二番目の「お」が「つ」に変わる一モーラ差。"}], "explanations": {"青い": "正解。あおい。", "赤い": "あかい。二番目の「お」が「か」に変わる一モーラ差。", "甘い": "あまい。二番目の「お」が「ま」に変わる一モーラ差。", "荒い": "あらい。二番目の「お」が「ら」に変わる一モーラ差。", "暑い": "あつい。二番目の「お」が「つ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "青い"}, "level_3": {"options": [{"text": "青い", "is_correct": true, "explanation": "晴れた空の色なので自然。"}, {"text": "甘い", "is_correct": false, "explanation": "意味：空に味はない。"}, {"text": "痛い", "is_correct": false, "explanation": "意味：空が痛いということはない。"}, {"text": "若い", "is_correct": false, "explanation": "連語：「空が若い」という結びつきはない。"}], "explanations": {"青い": "晴れた空の色なので自然。", "甘い": "意味：空に味はない。", "痛い": "意味：空が痛いということはない。", "若い": "連語：「空が若い」という結びつきはない。"}, "sentence_index": 0, "correct_answer": "青い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は青いのかさを持っている。", "explanation": "活用の誤り：い形容詞「青い」は「の」を挟まず名詞を直接修飾する。"}, {"text": "彼女は青くかさを持っている。", "explanation": "活用の誤り：名詞の前では連用形「青く」ではなく「青い」。"}, {"text": "彼女はかさを青い持っている。", "explanation": "語順の誤り：「青い」は名詞「かさ」の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51417, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海がとても青いだ。", "corrected_sentence": "海がとても青い。", "error_description": "活用の誤り：い形容詞に「だ」はつけない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "青い", "is_correct": true, "explanation": "名詞「服」を修飾する連体形。"}, {"text": "青く", "is_correct": false, "explanation": "連用形で、名詞の前には置けない。"}, {"text": "青くて", "is_correct": false, "explanation": "て形で、名詞を直接修飾しない。"}, {"text": "青ければ", "is_correct": false, "explanation": "仮定形で、名詞の前には置けない。"}], "correct_form": "青い", "base_form": "青い", "form_label": "連体形", "sentence_index": 1, "explanations": {"青い": "名詞「服」を修飾する連体形。", "青く": "連用形で、名詞の前には置けない。", "青くて": "て形で、名詞を直接修飾しない。", "青ければ": "仮定形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
