INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51417, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。読みはあおい。"}, {"text": "淡い", "is_correct": false, "explanation": "あわい。真ん中の「お」が「わ」。"}, {"text": "多い", "is_correct": false, "explanation": "おおい。頭の「あ」が「お」。"}, {"text": "痛い", "is_correct": false, "explanation": "いたい。頭の「あお」が「いた」。"}], "explanations": {"青い": "正解。読みはあおい。", "淡い": "あわい。真ん中の「お」が「わ」。", "多い": "おおい。頭の「あ」が「お」。", "痛い": "いたい。頭の「あお」が「いた」。"}, "sentence_index": null, "correct_answer": "青い"}, "level_3": {"options": [{"text": "青い", "is_correct": true, "explanation": "車の色を表すので自然。"}, {"text": "速い", "is_correct": false, "explanation": "意味：「速い」は動きの性質で、色を表さない。"}, {"text": "寒い", "is_correct": false, "explanation": "意味：「寒い」は気温を表し、色には使わない。"}, {"text": "痛い", "is_correct": false, "explanation": "意味：色が痛いということはない。"}], "explanations": {"青い": "車の色を表すので自然。", "速い": "意味：「速い」は動きの性質で、色を表さない。", "寒い": "意味：「寒い」は気温を表し、色には使わない。", "痛い": "意味：色が痛いということはない。"}, "sentence_index": 6, "correct_answer": "青い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の上から湖が青い見えた。", "explanation": "語順の誤り：「青い」は「湖」の前に置く。"}, {"text": "山の上から青いな湖が見えた。", "explanation": "活用の誤り：い形容詞に「な」はつけない。"}, {"text": "山の上から青いの湖が見えた。", "explanation": "活用の誤り：「青い」は「の」を挟まず名詞を修飾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51417, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この花は青いでした。", "corrected_sentence": "この花は青かったです。", "error_description": "活用の誤り：い形容詞の過去は「青いでした」ではなく「青かったです」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "青い", "is_correct": true, "explanation": "名詞「ペン」を修飾する連体形。"}, {"text": "青く", "is_correct": false, "explanation": "連用形は名詞を修飾できない。"}, {"text": "青くて", "is_correct": false, "explanation": "て形は名詞の前には置けない。"}, {"text": "青かろう", "is_correct": false, "explanation": "推量形で、ここでは使えない。"}], "correct_form": "青い", "base_form": "青い", "form_label": "連体形", "sentence_index": 7, "explanations": {"青い": "名詞「ペン」を修飾する連体形。", "青く": "連用形は名詞を修飾できない。", "青くて": "て形は名詞の前には置けない。", "青かろう": "推量形で、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
