INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51419, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "正解。くま。"}, {"text": "草", "is_correct": false, "explanation": "くさ。二番目の「ま」が「さ」に変わる一モーラ差。"}, {"text": "雲", "is_correct": false, "explanation": "くも。二番目の「ま」が「も」に変わる一モーラ差。"}, {"text": "靴", "is_correct": false, "explanation": "くつ。二番目の「ま」が「つ」に変わる一モーラ差。"}, {"text": "島", "is_correct": false, "explanation": "しま。最初の「く」が「し」に変わる一モーラ差。"}], "explanations": {"熊": "正解。くま。", "草": "くさ。二番目の「ま」が「さ」に変わる一モーラ差。", "雲": "くも。二番目の「ま」が「も」に変わる一モーラ差。", "靴": "くつ。二番目の「ま」が「つ」に変わる一モーラ差。", "島": "しま。最初の「く」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "熊は山にすむので自然。"}, {"text": "鯨", "is_correct": false, "explanation": "意味：鯨は海にすみ、山では見られない。"}, {"text": "イルカ", "is_correct": false, "explanation": "意味：イルカは海の動物で、山にはいない。"}, {"text": "波", "is_correct": false, "explanation": "意味：波は海のもので、山では見られない。"}], "explanations": {"熊": "熊は山にすむので自然。", "鯨": "意味：鯨は海にすみ、山では見られない。", "イルカ": "意味：イルカは海の動物で、山にはいない。", "波": "意味：波は海のもので、山では見られない。"}, "sentence_index": 0, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熊が川を魚をとっている。", "explanation": "助詞の誤り：場所は「を」ではなく「で」で表す。"}, {"text": "一冊の熊が川で魚をとっている。", "explanation": "助数詞の誤り：熊は「冊」ではなく「頭」や「匹」で数える。"}, {"text": "熊を川で魚がとっている。", "explanation": "意味の誤り：魚をとるのは熊なので、「熊が」「魚を」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51419, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熊は冬を眠る。", "corrected_sentence": "熊は冬に眠る。", "error_description": "助詞の誤り：時を表すときは「を」ではなく「に」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51419, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時を表す「に」で、「冬に眠る」は自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表し、季節の時点には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、時には使えない。"}, {"text": "を", "is_correct": false, "explanation": "「眠る」は自動詞で、「冬を」は不自然。"}], "correct_answer": "に", "explanations": {"に": "時を表す「に」で、「冬に眠る」は自然。", "で": "「で」は場所・手段を表し、季節の時点には使わない。", "へ": "「へ」は方向を表し、時には使えない。", "を": "「眠る」は自動詞で、「冬を」は不自然。"}, "error_tags": {"で": "location_vs_target", "へ": "direction", "を": "object_marking"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51419, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熊", "is_correct": true, "explanation": "正解。読みはくま。"}, {"text": "暇", "is_correct": false, "explanation": "ひま。頭の「く」が「ひ」。"}, {"text": "櫛", "is_correct": false, "explanation": "くし。終わりの「ま」が「し」。"}, {"text": "釘", "is_correct": false, "explanation": "くぎ。終わりの「ま」が「ぎ」。"}], "explanations": {"熊": "正解。読みはくま。", "暇": "ひま。頭の「く」が「ひ」。", "櫛": "くし。終わりの「ま」が「し」。", "釘": "くぎ。終わりの「ま」が「ぎ」。"}, "sentence_index": null, "correct_answer": "熊"}, "level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "危ない熊に会ったら逃げるので自然。"}, {"text": "友達", "is_correct": false, "explanation": "意味：友達に会って逃げるのはおかしい。"}, {"text": "先生", "is_correct": false, "explanation": "意味：先生から逃げる理由がなく不自然。"}, {"text": "家族", "is_correct": false, "explanation": "意味：家族に会って静かに逃げるのはおかしい。"}], "explanations": {"熊": "危ない熊に会ったら逃げるので自然。", "友達": "意味：友達に会って逃げるのはおかしい。", "先生": "意味：先生から逃げる理由がなく不自然。", "家族": "意味：家族に会って静かに逃げるのはおかしい。"}, "sentence_index": 6, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村の近くを熊が出た。", "explanation": "助詞の誤り：場所は「を」ではなく「に」で表す。"}, {"text": "村の近くに一枚の熊が出た。", "explanation": "助数詞の誤り：熊は「枚」で数えない。"}, {"text": "村の近くに熊があった。", "explanation": "動詞の誤り：生き物の熊には「ある」ではなく「いる」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d892af7-a4cb-424c-bb3e-7d86c00adb3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
