INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものをぴったりくっつけたり、一つにしたりすること。", "primary_collocate": null, "pronunciation": "あわせる", "ipa": "awaseɾɯ", "syllable_count": 4, "sentences": [{"text": "両手を合わせる。", "target_word": "合わせる", "complexity_tier": "T3", "furigana": "りょうて あ", "sentence_source": "generated"}, {"text": "二枚の紙を合わせてはった。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "にまい かみ あ", "sentence_source": "generated"}, {"text": "二つの箱をテープで合わせた。", "target_word": "合わせた", "complexity_tier": "T3", "furigana": "ふた はこ あ", "sentence_source": "generated"}, {"text": "板の端をぴったり合わせる。", "target_word": "合わせる", "complexity_tier": "T3", "furigana": "いた はし あ", "sentence_source": "generated"}, {"text": "二つの色を合わせて緑にした。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "ふた いろ あ みどり", "sentence_source": "generated"}, {"text": "手を合わせている人がいる。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "て あ ひと", "sentence_source": "generated"}, {"text": "布を合わせられるかな。", "target_word": "合わせられる", "complexity_tier": "T3", "furigana": "ぬの あ", "sentence_source": "generated"}, {"text": "パズルのピースを合わせた。", "target_word": "合わせた", "complexity_tier": "T3", "furigana": "あ", "sentence_source": "generated"}, {"text": "三人のお金を合わせる。", "target_word": "合わせる", "complexity_tier": "T3", "furigana": "さんにん かね あ", "sentence_source": "generated"}, {"text": "穴を合わせないとねじが入らない。", "target_word": "合わせない", "complexity_tier": "T3", "furigana": "あな あ はい", "sentence_source": "generated"}], "morphological_forms": [{"form": "合わせた", "label": "活用"}, {"form": "合わせて", "label": "活用"}, {"form": "合わせない", "label": "活用"}, {"form": "合わせられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 二つのものをくっつけて一つにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted