INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51505, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丁寧", "is_correct": true, "explanation": "正解。「ていねい」と読む。"}, {"text": "定例", "is_correct": false, "explanation": "「ていれい」と読む。「ね」が「れ」に変わる一モーラ差。"}, {"text": "訂正", "is_correct": false, "explanation": "「ていせい」と読む。「ね」が「せ」に変わる一モーラ差。"}, {"text": "定年", "is_correct": false, "explanation": "「ていねん」と読む。最後の「い」が「ん」に変わる一モーラ差。"}, {"text": "提携", "is_correct": false, "explanation": "「ていけい」と読む。「ね」が「け」に変わる一モーラ差。"}], "explanations": {"丁寧": "正解。「ていねい」と読む。", "定例": "「ていれい」と読む。「ね」が「れ」に変わる一モーラ差。", "訂正": "「ていせい」と読む。「ね」が「せ」に変わる一モーラ差。", "定年": "「ていねん」と読む。最後の「い」が「ん」に変わる一モーラ差。", "提携": "「ていけい」と読む。「ね」が「け」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "丁寧"}, "level_3": {"options": [{"text": "丁寧", "is_correct": true, "explanation": "心をこめて字を書くようすを表す。"}, {"text": "不便", "is_correct": false, "explanation": "意味：「不便に字を書く」とは言わない。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：「退屈に字を書く」は不自然な結びつき。"}, {"text": "迷惑", "is_correct": false, "explanation": "連語：「迷惑に書く」とは言わない。"}], "explanations": {"丁寧": "心をこめて字を書くようすを表す。", "不便": "意味：「不便に字を書く」とは言わない。", "退屈": "意味：「退屈に字を書く」は不自然な結びつき。", "迷惑": "連語：「迷惑に書く」とは言わない。"}, "sentence_index": 0, "correct_answer": "丁寧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱を丁寧が包んでいる。", "explanation": "助詞の混同：「丁寧」は連用には「に」をとり、「が」では副詞的に使えない。"}, {"text": "丁寧に箱を包んだている。", "explanation": "活用・アスペクトの誤り：「包んだている」は誤った形で、「包んでいる」が正しい。"}, {"text": "箱を包んでいるに丁寧。", "explanation": "語順の誤り：「丁寧に」は動詞の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, v