INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は丁寧だ説明をしてくれた。", "corrected_sentence": "先生は丁寧な説明をしてくれた。", "error_description": "名詞「説明」を修飾するので終止形「丁寧だ」ではなく連体形「丁寧な」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丁寧", "is_correct": true, "explanation": "空欄の後に「な」が続くので語幹「丁寧」が入る。"}, {"text": "丁寧に", "is_correct": false, "explanation": "「丁寧にな説明」となり非文。"}, {"text": "丁寧だ", "is_correct": false, "explanation": "「丁寧だな説明」となり名詞を修飾できない。"}, {"text": "丁寧さ", "is_correct": false, "explanation": "名詞形で「丁寧さな説明」は非文。"}], "correct_form": "丁寧", "base_form": "丁寧", "form_label": "連体形（な形）", "sentence_index": 1, "explanations": {"丁寧": "空欄の後に「な」が続くので語幹「丁寧」が入る。", "丁寧に": "「丁寧にな説明」となり非文。", "丁寧だ": "「丁寧だな説明」となり名詞を修飾できない。", "丁寧さ": "名詞形で「丁寧さな説明」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
