INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51509, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し「今日の給食」について述べる。"}, {"text": "を", "is_correct": false, "explanation": "「給食をカレーだ」は目的語標示で非文。"}, {"text": "で", "is_correct": false, "explanation": "「給食でカレーだ」は場所・手段で文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「給食にカレーだ」は着点の意味で不自然。"}], "correct_answer": "は", "explanations": {"は": "主題を示し「今日の給食」について述べる。", "を": "「給食をカレーだ」は目的語標示で非文。", "で": "「給食でカレーだ」は場所・手段で文が成立しない。", "に": "「給食にカレーだ」は着点の意味で不自然。"}, "error_tags": {"を": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
